/* Bank soal bawaan. Bentuk tiap soal: [pertanyaan, [pilihan...], huruf jawaban, pembahasan] */
(function () {
  var m = function (a) { return a.map(function (x) { return { q: x[0], o: x[1], a: x[2], e: x[3] }; }); };
  window.MO_EXAM_BANKS = [
    {
      id: 'etika-profesi-hukum-p8',
      title: 'Pertemuan 8: Profesi Advokat di Indonesia',
      course: 'Etika Profesi Hukum',
      questions: m([
        ['Sejak kapan profesi advokat dikenal di Indonesia berdasarkan materi PDF?', ['Sejak Indonesia merdeka tahun 1945.', 'Sejak zaman kolonial Belanda.', 'Sejak diberlakukannya UU Nomor 18 Tahun 2003.', 'Sejak terbentuknya Mahkamah Agung.'], 'B', 'Profesi advokat sudah dikenal sejak zaman kolonial Belanda, jadi sudah ada sebelum Indonesia merdeka, meskipun keberadaannya masih terbatas.'],
        ['Pada masa kolonial Belanda, keberadaan advokat terutama ditemukan di ...', ['Seluruh desa di wilayah Indonesia.', 'Wilayah pedalaman dan pedesaan.', 'Kota-kota besar yang memiliki pengadilan landraad.', 'Wilayah yang tidak memiliki lembaga peradilan.'], 'C', 'Advokat belum tersebar merata. Keberadaannya terutama di kota-kota besar yang memiliki pengadilan landraad.'],
        ['Apakah yang dimaksud dengan landraad dalam sejarah profesi advokat?', ['Organisasi advokat pada masa kolonial.', 'Salah satu jenis pengadilan pada masa kolonial Belanda yang terutama menangani perkara penduduk pribumi.', 'Lembaga pendidikan hukum bagi masyarakat pribumi.', 'Lembaga pengawasan etik advokat.'], 'B', 'Landraad adalah salah satu jenis pengadilan dalam sistem peradilan kolonial Belanda, dan berkaitan dengan perkembangan profesi advokat pada masa itu.'],
        ['Mengapa profesi advokat pada masa kolonial Belanda masih didominasi oleh orang Belanda?', ['Karena penduduk pribumi dilarang memahami hukum.', 'Karena seluruh pengadilan hanya menerima advokat Belanda.', 'Karena pendidikan hukum, kesempatan profesional, serta akses sosial dan politik belum merata.', 'Karena masyarakat pribumi tidak membutuhkan bantuan hukum.'], 'C', 'Tiga faktor penting: akses pendidikan hukum tidak merata, ketimpangan sosial dan politik, serta perkembangan profesi yang berpusat di kota-kota tertentu.'],
        ['Salah satu tonggak penting pengaturan profesi advokat setelah Indonesia merdeka adalah ...', ['UU Nomor 16 Tahun 2011.', 'UU Nomor 18 Tahun 2003.', 'UU Nomor 48 Tahun 2009.', 'UU Nomor 1 Tahun 1974.'], 'B', 'UU Nomor 18 Tahun 2003 tentang Advokat menjadi landasan hukum nasional yang mengatur pengertian, persyaratan pengangkatan, pelaksanaan profesi, hak, kewajiban, dan pengawasan etik advokat.'],
        ['Menurut Pasal 1 angka 1 UU Nomor 18 Tahun 2003, advokat adalah ...', ['Setiap orang yang memiliki pengetahuan tentang hukum.', 'Orang yang bekerja di lembaga peradilan.', 'Orang yang berprofesi memberikan jasa hukum, baik di dalam maupun di luar pengadilan, dan memenuhi persyaratan berdasarkan undang-undang.', 'Pegawai negara yang bertugas memberikan bantuan hukum.'], 'C', 'Tiga unsur utama pengertian advokat: profesi, jasa hukum, dan pemenuhan persyaratan hukum. Seseorang tidak otomatis menjadi advokat hanya karena memahami hukum.'],
        ['Seseorang lulusan fakultas hukum sering memberikan pendapat mengenai persoalan hukum. Apakah ia otomatis berstatus advokat?', ['Ya, karena telah menyelesaikan pendidikan hukum.', 'Ya, selama pendapatnya benar.', 'Tidak, karena harus memenuhi persyaratan serta ketentuan hukum untuk menjalankan profesi advokat.', 'Tidak, karena hanya hakim yang boleh memberikan pendapat hukum.'], 'C', 'Pengetahuan hukum tidak sama dengan status profesi advokat. Status advokat berkaitan dengan pemenuhan persyaratan dan ketentuan perundang-undangan.'],
        ['Apa yang dimaksud dengan litigasi?', ['Penyelesaian persoalan hukum melalui proses pengadilan.', 'Penyelesaian persoalan hukum melalui negosiasi.', 'Pemberian konsultasi hukum.', 'Penyusunan kontrak di luar pengadilan.'], 'A', 'Litigasi adalah penanganan perkara melalui proses peradilan, misalnya menyusun gugatan, jawaban atas gugatan, mendampingi terdakwa, dan menyampaikan argumentasi di persidangan.'],
        ['Berikut ini yang termasuk kegiatan nonlitigasi adalah ...', ['Menyampaikan argumentasi di persidangan.', 'Mengajukan gugatan perdata.', 'Menyusun jawaban atas gugatan.', 'Membantu perundingan dan mendampingi klien dalam mediasi.'], 'D', 'Nonlitigasi adalah pelayanan atau penyelesaian persoalan hukum di luar proses persidangan, misalnya konsultasi hukum, penyusunan kontrak, somasi, negosiasi, dan mediasi.'],
        ['Mengapa profesi advokat perlu diatur oleh undang-undang?', ['Agar advokat memiliki kekuasaan lebih tinggi daripada hakim.', 'Agar setiap orang bebas membuka kantor hukum.', 'Agar terdapat standar kompetensi, persyaratan, tanggung jawab, dan etika profesi.', 'Agar advokat dapat memenangkan seluruh perkara.'], 'C', 'Advokat menangani kepentingan hukum orang lain. Tanpa standar, orang yang tidak kompeten dapat merugikan klien melalui nasihat atau tindakan hukum yang salah.'],
        ['Berdasarkan materi PDF, berapakah usia minimal seseorang untuk menjadi advokat?', ['21 tahun.', '22 tahun.', '24 tahun.', '25 tahun.'], 'D', 'Usia minimal adalah 25 tahun. Seseorang yang berusia 24 tahun belum memenuhi persyaratan meskipun sudah menyelesaikan pendidikan hukum.'],
        ['Manakah yang termasuk persyaratan kewarganegaraan untuk menjadi advokat?', ['Harus warga negara asing.', 'Harus warga Negara Indonesia.', 'Harus memiliki kewarganegaraan ganda.', 'Tidak ada ketentuan kewarganegaraan.'], 'B', 'Calon advokat berdasarkan UU Nomor 18 Tahun 2003 harus berstatus WNI karena profesi dijalankan berdasarkan sistem hukum nasional Indonesia.'],
        ['Seorang calon advokat adalah WNI, tetapi bertempat tinggal di luar Indonesia. Bagaimana kedudukannya berdasarkan persyaratan dalam PDF?', ['Sudah memenuhi seluruh persyaratan.', 'Belum memenuhi persyaratan tempat tinggal di Indonesia.', 'Otomatis dapat diangkat menjadi advokat.', 'Tidak perlu memperhatikan tempat tinggal karena sudah menjadi WNI.'], 'B', 'Kewarganegaraan dan tempat tinggal adalah dua persyaratan berbeda. Memenuhi syarat WNI tidak otomatis memenuhi syarat bertempat tinggal di Indonesia.'],
        ['Mengapa calon advokat tidak boleh berstatus sebagai pegawai negeri atau pejabat negara menurut materi?', ['Karena pegawai negeri tidak boleh mempelajari hukum.', 'Karena advokat harus memiliki kantor pribadi.', 'Karena perlu menjaga independensi profesi dan menghindari pertentangan kedudukan serta kewajiban.', 'Karena advokat harus bekerja di pengadilan.'], 'C', 'Advokat harus independen dalam memperjuangkan kepentingan hukum klien, sedangkan pegawai negeri dan pejabat negara memiliki kedudukan serta kewajiban dalam penyelenggaraan pemerintahan.'],
        ['Pendidikan tinggi hukum diperlukan bagi calon advokat terutama untuk ...', ['Mendapatkan gelar akademik sebanyak mungkin.', 'Membekali pengetahuan dasar hukum dan keterampilan penalaran serta argumentasi hukum.', 'Menggantikan seluruh proses pendidikan profesi.', 'Menjamin kemenangan dalam persidangan.'], 'B', 'Pendidikan hukum memberi dasar pengetahuan tentang sistem hukum Indonesia, hukum pidana, perdata, hukum acara, hukum tata negara, administrasi negara, penafsiran hukum, dan penyusunan dokumen hukum.'],
        ['Apakah kepanjangan PKPA?', ['Pendidikan Khusus Pengadilan Advokat.', 'Pendidikan Kompetensi Profesi Akademik.', 'Pendidikan Khusus Profesi Advokat.', 'Pendidikan Keahlian Praktik Advokat.'], 'C', 'PKPA adalah Pendidikan Khusus Profesi Advokat, yaitu pembekalan khusus tentang praktik dan keterampilan profesi advokat.'],
        ['Apa perbedaan utama PKPA dan ujian profesi advokat?', ['PKPA merupakan ujian, sedangkan ujian profesi merupakan pendidikan.', 'PKPA adalah pendidikan khusus, sedangkan ujian profesi menilai kesiapan calon advokat untuk memasuki profesi.', 'Keduanya merupakan istilah yang sama.', 'PKPA hanya dilakukan setelah seseorang diangkat menjadi advokat.'], 'B', 'PKPA membekali calon advokat dengan pengetahuan dan keterampilan. Ujian profesi oleh Organisasi Advokat menilai kesiapan calon advokat. Keduanya tahapan yang berbeda.'],
        ['Berapa lama minimal calon advokat harus menjalani magang berdasarkan materi PDF?', ['Enam bulan.', 'Satu tahun.', 'Dua tahun secara terus-menerus.', 'Tiga tahun secara tidak berurutan.'], 'C', 'Magang dilakukan sekurang-kurangnya dua tahun secara terus-menerus di kantor advokat, agar calon advokat memperoleh pengalaman praktik langsung.'],
        ['Berikut ini yang bukan merupakan hal yang dipelajari selama magang adalah ...', ['Menganalisis persoalan hukum klien.', 'Menyusun gugatan dan jawaban.', 'Menjaga kerahasiaan informasi klien.', 'Mengabaikan kode etik demi kepentingan klien.'], 'D', 'Magang juga mengajarkan penerapan kode etik dalam praktik. Advokat tidak boleh mengabaikan etika hanya demi keinginan klien.'],
        ['Dalam persyaratan riwayat pidana calon advokat, materi PDF menekankan bahwa ketentuan lima tahun atau lebih mengacu pada ...', ['Lamanya seseorang menjalani hukuman.', 'Ancaman pidana terhadap tindak pidananya.', 'Lamanya seseorang berada di tahanan.', 'Banyaknya perkara yang pernah dihadapi.'], 'B', 'Perhatikan perbedaan ancaman pidana dan hukuman yang dijatuhkan. Rumusan dalam materi mengacu pada ancaman pidana untuk tindak pidananya, bukan semata lamanya hukuman yang dijalani.'],
        ['Manakah yang paling mencerminkan integritas seorang advokat?', ['Bersedia melakukan segala cara demi memenangkan perkara.', 'Mengikuti semua perintah klien tanpa pertimbangan.', 'Tetap memegang prinsip hukum dan etika meskipun mendapat tekanan atau godaan.', 'Mengutamakan keuntungan pribadi di atas kepentingan hukum.'], 'C', 'Integritas adalah konsistensi memegang prinsip kejujuran dan etika. Advokat tidak boleh memalsukan fakta, dokumen, atau keterangan, bahkan ketika klien memintanya.'],
        ['Berikut ini sembilan kelompok persyaratan menjadi advokat. Manakah urutan yang benar?', ['WNI, bertempat tinggal di Indonesia, bukan PNS/pejabat negara, usia minimal 25 tahun, pendidikan tinggi hukum, PKPA dan ujian profesi, magang dua tahun, persyaratan riwayat pidana, dan integritas.', 'WNI, usia minimal 21 tahun, pendidikan hukum, magang enam bulan, dan pengalaman kerja.', 'WNI, usia minimal 25 tahun, menjadi pegawai negeri, mengikuti PKPA, dan memiliki kantor hukum.', 'Pendidikan tinggi hukum, usia minimal 25 tahun, menjadi hakim, dan mengikuti ujian pengadilan.'], 'A', 'Kesembilan kelompok persyaratan meliputi aspek administratif, pendidikan, pengalaman, riwayat pidana, dan kualitas moral. PDF juga mengingatkan bahwa pengangkatan dan pelaksanaan profesi memperhatikan ketentuan sumpah atau janji advokat.'],
        ['Berikut ini yang termasuk ruang lingkup jasa hukum advokat adalah ...', ['Hanya membela terdakwa dalam perkara pidana.', 'Hanya mewakili klien dalam persidangan.', 'Konsultasi, bantuan hukum, menjalankan kuasa, mewakili, mendampingi, membela, dan tindakan hukum lainnya.', 'Hanya menyusun dokumen perjanjian.'], 'C', 'Jasa hukum advokat luas, baik di dalam maupun di luar pengadilan, dan tidak terbatas pada membela klien di persidangan.'],
        ['Seorang istri datang kepada advokat untuk mengetahui prosedur perceraian, persyaratan pengajuan perkara, dan kemungkinan alat bukti. Bentuk jasa hukum yang diberikan adalah ...', ['Menjalankan kuasa.', 'Konsultasi hukum.', 'Prodeo.', 'Duplik.'], 'B', 'Konsultasi hukum adalah pemberian penjelasan, pendapat, dan saran berdasarkan hukum. Advokat membantu klien memahami persoalan, hak, kewajiban, risiko, serta pilihan penyelesaian.'],
        ['Apa perbedaan konsultasi hukum dan mewakili klien?', ['Konsultasi berfokus pada penjelasan dan saran hukum, sedangkan mewakili berarti bertindak untuk kepentingan klien dalam lingkup kewenangan yang dimiliki.', 'Konsultasi selalu dilakukan di pengadilan, sedangkan mewakili dilakukan di luar pengadilan.', 'Keduanya tidak memiliki perbedaan.', 'Mewakili tidak memerlukan kewenangan dari klien.'], 'A', 'Seseorang dapat berkonsultasi dengan advokat tanpa langsung menunjuknya sebagai kuasa hukum untuk menangani perkara.'],
        ['Dalam konteks materi PDF, bantuan hukum dapat berbentuk ...', ['Pemberian bantuan untuk menangani persoalan hukum melalui penjelasan, penyusunan dokumen, pendampingan, dan tindakan hukum lain.', 'Hanya pembebasan biaya perkara.', 'Hanya pemberian nasihat secara lisan.', 'Hanya pembelaan dalam perkara pidana.'], 'A', 'Bantuan hukum mencakup berbagai bentuk bantuan untuk menyelesaikan persoalan hukum, termasuk pengajuan gugatan dan permohonan.'],
        ['Apa perbedaan gugatan dan permohonan?', ['Gugatan selalu diajukan tanpa pihak lain, sedangkan permohonan selalu melibatkan tergugat.', 'Gugatan adalah tuntutan hak dalam suatu sengketa, sedangkan permohonan adalah pengajuan kepada pengadilan untuk memperoleh penetapan atau keputusan mengenai suatu hal.', 'Gugatan dan permohonan adalah istilah yang sama.', 'Gugatan hanya untuk perkara pidana, sedangkan permohonan hanya untuk perkara perdata.'], 'B', 'Gugatan umumnya melibatkan pihak yang merasa haknya dilanggar dengan pihak yang dianggap bertanggung jawab. Permohonan tidak selalu berbentuk sengketa antara penggugat dan tergugat.'],
        ['Ahmad meminjamkan uang kepada Budi. Saat jatuh tempo, Budi tidak membayar dan tidak tercapai penyelesaian baik-baik. Jika persyaratan hukumnya terpenuhi, tindakan yang dapat dipertimbangkan Ahmad adalah ...', ['Mengajukan gugatan.', 'Mengajukan duplik terlebih dahulu.', 'Meminta putusan tanpa proses.', 'Mengajukan permohonan magang.'], 'A', 'Gugatan dapat diajukan untuk menuntut hak yang dilanggar melalui pengadilan. Advokat dapat membantu menilai dasar hukum dan menyusun gugatan.'],
        ['Apakah perbedaan pro bono dan prodeo?', ['Pro bono adalah pembebasan biaya perkara, sedangkan prodeo adalah jasa hukum gratis.', 'Pro bono adalah jasa hukum secara cuma-cuma, sedangkan prodeo adalah pembebasan biaya perkara.', 'Pro bono dan prodeo sama-sama berarti konsultasi hukum berbayar.', 'Pro bono merupakan bantuan hakim, sedangkan prodeo merupakan bantuan advokat.'], 'B', 'Pro bono = jasa hukumnya gratis. Prodeo = biaya perkaranya dibebaskan. Keduanya dapat membantu masyarakat tidak mampu, tetapi mekanismenya berbeda.'],
        ['Seorang advokat membantu masyarakat tidak mampu menangani perkara tanpa meminta honorarium. Istilah yang tepat adalah ...', ['Prodeo.', 'Litigasi.', 'Pro bono.', 'Duplik.'], 'C', 'Pro bono adalah pemberian jasa hukum secara cuma-cuma kepada pihak yang membutuhkan. Fokusnya layanan profesional advokat, bukan pembebasan biaya pengadilan.'],
        ['Seorang warga tidak mampu mengajukan perkara dan memenuhi persyaratan untuk memperoleh pembebasan biaya pengadilan. Hal ini disebut ...', ['Pro bono.', 'Prodeo.', 'PKPA.', 'Nonlitigasi.'], 'B', 'Prodeo berkaitan dengan pembebasan biaya perkara di pengadilan. Fokusnya biaya proses perkara, bukan honorarium advokat.'],
        ['Apa yang dimaksud dengan menjalankan kuasa?', ['Memberikan nasihat hukum tanpa bertindak lebih lanjut.', 'Melakukan tindakan hukum berdasarkan kewenangan yang diberikan klien.', 'Mengambil alih seluruh hak klien.', 'Mengambil keputusan tanpa persetujuan klien.'], 'B', 'Kuasa adalah kewenangan yang diberikan seseorang kepada pihak lain untuk melakukan tindakan tertentu atas nama atau untuk kepentingannya, umumnya dituangkan dalam surat kuasa.'],
        ['Apakah advokat boleh melakukan seluruh tindakan atas nama klien setelah menerima surat kuasa?', ['Boleh, karena surat kuasa memberikan kewenangan tanpa batas.', 'Boleh, selama klien membayar honorarium.', 'Tidak, advokat harus bertindak sesuai lingkup kewenangan yang diberikan dan mematuhi hukum serta etika.', 'Tidak, advokat tidak boleh melakukan tindakan hukum apa pun.'], 'C', 'Kuasa memiliki batas. Advokat tidak boleh menganggap dirinya otomatis berwenang melakukan tindakan di luar lingkup kuasa atau tindakan yang memerlukan persetujuan khusus.'],
        ['Apa perbedaan menjalankan kuasa dan mewakili klien?', ['Menjalankan kuasa menekankan pelaksanaan kewenangan yang diberikan, sedangkan mewakili menekankan tindakan untuk kepentingan pihak yang diwakili.', 'Menjalankan kuasa hanya dilakukan hakim, sedangkan mewakili hanya dilakukan jaksa.', 'Menjalankan kuasa berarti mendampingi, sedangkan mewakili berarti memberikan konsultasi.', 'Tidak ada perbedaan sama sekali.'], 'A', 'Keduanya saling berkaitan. Advokat dapat menjalankan kuasa sekaligus mewakili klien dalam perkara tertentu, tetapi titik tekan pengertiannya berbeda.'],
        ['Seorang advokat mendampingi seseorang yang menjalani pemeriksaan dalam perkara pidana untuk memastikan hak-haknya dihormati. Kegiatan tersebut adalah ...', ['Permohonan.', 'Pendampingan hukum.', 'Prodeo.', 'Pengajuan gugatan.'], 'B', 'Pendampingan berarti memberikan bantuan dan dukungan profesional selama proses hukum: membantu klien memahami prosedur, mempersiapkan diri, dan menghadapi proses hukum dengan lebih terarah.'],
        ['Apa prinsip utama dalam membela kepentingan hukum klien?', ['Advokat harus melakukan apa pun untuk memenangkan perkara.', 'Advokat harus mengikuti semua keinginan klien.', 'Advokat memperjuangkan kepentingan klien dengan tetap mematuhi hukum dan etika profesi.', 'Advokat boleh memalsukan bukti jika diperlukan.'], 'C', 'Membela bukan berarti menghalalkan segala cara. Advokat wajib memperjuangkan kepentingan hukum klien dengan cara yang sah dan etis.'],
        ['Apa yang dimaksud dengan somasi?', ['Putusan pengadilan yang bersifat final.', 'Teguran atau peringatan kepada pihak tertentu agar memenuhi kewajiban yang dianggap belum dipenuhi.', 'Tanggapan penggugat terhadap jawaban tergugat.', 'Surat pengangkatan advokat.'], 'B', 'Somasi adalah teguran atau peringatan, misalnya kepada pihak yang belum membayar utang. Somasi bukan putusan pengadilan dan tidak otomatis menjamin kewajiban akan dipenuhi.'],
        ['Dalam perkara perdata, siapakah yang disebut penggugat?', ['Pihak yang diajukan sebagai saksi.', 'Pihak yang mengajukan gugatan ke pengadilan.', 'Pihak yang digugat oleh orang lain.', 'Pihak yang memberikan putusan.'], 'B', 'Penggugat adalah pihak yang mengajukan gugatan karena merasa hak atau kepentingannya perlu dilindungi atau dipulihkan.'],
        ['Siapakah yang disebut tergugat?', ['Pihak yang mengajukan gugatan.', 'Pihak yang memberikan putusan.', 'Pihak yang digugat oleh penggugat.', 'Pihak yang menjadi kuasa hukum.'], 'C', 'Tergugat adalah pihak yang digugat. Ia berhak menjawab gugatan dan membela kepentingannya sesuai hukum acara.'],
        ['Apakah yang dimaksud dengan jawaban dalam proses perkara perdata?', ['Tanggapan tergugat terhadap gugatan yang diajukan penggugat.', 'Tanggapan penggugat terhadap replik.', 'Putusan hakim terhadap perkara.', 'Tanggapan saksi terhadap pertanyaan advokat.'], 'A', 'Jawaban adalah tanggapan tergugat terhadap gugatan. Isinya dapat berupa bantahan fakta, penjelasan kronologi berbeda, atau alasan hukum.'],
        ['Ahmad menggugat Budi. Budi memberikan jawaban atas gugatan. Selanjutnya Ahmad menanggapi jawaban Budi. Tanggapan Ahmad disebut ...', ['Gugatan.', 'Jawaban.', 'Replik.', 'Duplik.'], 'C', 'Replik adalah tanggapan penggugat terhadap jawaban tergugat. Ahmad sebagai penggugat memberikan replik.'],
        ['Setelah Ahmad memberikan replik, Budi kembali menanggapi replik tersebut. Tanggapan Budi disebut ...', ['Gugatan.', 'Duplik.', 'Permohonan.', 'Somasi.'], 'B', 'Duplik adalah tanggapan tergugat terhadap replik penggugat. Urutannya: gugatan (penggugat), jawaban (tergugat), replik (penggugat), duplik (tergugat). Kunci: replik dari penggugat, duplik dari tergugat.'],
        ['Menurut Bab 5 PDF, dua hal utama yang harus diperhatikan ketika advokat memberikan jasa hukum adalah ...', ['Honorarium dan popularitas klien.', 'Permintaan klien dan tidak adanya konflik kepentingan.', 'Hubungan keluarga dan jabatan klien.', 'Keinginan advokat dan keputusan hakim.'], 'B', 'Advokat pada umumnya memberikan jasa hukum berdasarkan permintaan klien, dan penerimaan perkara harus memperhatikan tidak adanya konflik kepentingan yang dilarang.'],
        ['Mengapa permintaan klien menjadi dasar penting dalam pemberian jasa hukum?', ['Agar advokat dapat bertindak sesuka hati.', 'Agar terbentuk hubungan profesional, diketahui persoalan yang ditangani, dan terdapat kewenangan yang sesuai.', 'Agar klien tidak dapat mengganti advokat.', 'Agar advokat dapat menentukan hasil putusan.'], 'B', 'Permintaan klien menjadi dasar untuk memahami kebutuhan hukum, menentukan lingkup pekerjaan, membangun hubungan profesional, dan memperoleh kewenangan sebelum bertindak atas nama klien.'],
        ['Apakah yang dimaksud konflik kepentingan?', ['Keadaan ketika advokat tidak mendapatkan honorarium.', 'Keadaan ketika kepentingan tertentu berbenturan dengan kewajiban profesional advokat terhadap klien.', 'Keadaan ketika klien tidak setuju dengan pendapat hakim.', 'Keadaan ketika advokat kalah dalam persidangan.'], 'B', 'Konflik kepentingan dapat mengganggu independensi, objektivitas, dan kemampuan advokat menjalankan tugas profesionalnya.'],
        ['Mengapa konflik kepentingan harus dihindari?', ['Karena dapat mengurangi popularitas advokat.', 'Karena dapat menghambat proses pembayaran honorarium.', 'Karena dapat mengancam kerahasiaan klien, independensi advokat, dan kepercayaan masyarakat.', 'Karena advokat tidak boleh menangani perkara yang sulit.'], 'C', 'Tiga alasan utama: melindungi kerahasiaan klien, menjaga independensi advokat, dan menjaga kepercayaan masyarakat. Sebelum menerima perkara, periksa identitas para pihak, hubungan profesional sebelumnya, dan kemungkinan informasi rahasia yang relevan.'],
        ['Ahmad sedang bersengketa tanah dan belum meminta bantuan advokat. Seorang advokat langsung mengajukan gugatan atas nama Ahmad tanpa kewenangan darinya. Bagaimana tindakan tersebut dinilai berdasarkan PDF?', ['Benar, karena advokat boleh bertindak atas inisiatif sendiri.', 'Benar, selama advokat memahami hukum.', 'Tidak tepat, karena advokat memerlukan dasar hubungan profesional dan kewenangan yang sesuai untuk bertindak atas nama seseorang.', 'Benar, jika perkara tersebut menarik perhatian masyarakat.'], 'C', 'Advokat tidak otomatis berwenang bertindak atas nama seseorang hanya karena mengetahui persoalan hukumnya. Catatan: penyuluhan hukum dan bantuan hukum untuk kepentingan umum dapat dilakukan lewat program yang sah, dan itu berbeda dari bertindak sebagai kuasa tanpa kewenangan.'],
        ['Berdasarkan Bab 7 PDF, tiga alasan utama advokat dapat menolak memberikan jasa hukum adalah ...', ['Klien tidak terkenal, perkara sulit, dan honorarium kecil.', 'Bertentangan dengan hati nurani, tidak sesuai dengan keahlian, dan terdapat konflik kepentingan.', 'Klien berasal dari daerah berbeda, perkara lama, dan tidak populer.', 'Advokat sedang sibuk, klien tidak kaya, dan perkara tidak terkenal.'], 'B', 'Advokat tidak wajib menerima setiap permintaan jasa hukum, tetapi penolakan harus dilakukan secara bertanggung jawab dan sesuai hukum serta kode etik.'],
        ['Seorang klien meminta advokat membuat dokumen palsu untuk memenangkan perkara. Apa tindakan yang tepat?', ['Memenuhi permintaan karena klien adalah pihak yang membayar.', 'Membuat dokumen palsu selama tidak diketahui hakim.', 'Menolak karena tindakan tersebut bertentangan dengan hukum dan etika profesi.', 'Menyetujui dengan syarat klien bertanggung jawab sendiri.'], 'C', 'Advokat tidak boleh menghalalkan segala cara demi kemenangan. Hati nurani, kejujuran, dan integritas mengharuskan advokat menolak tindakan yang melanggar hukum atau kewajiban profesionalnya.'],
        ['Seorang advokat berkeahlian utama hukum perdata didatangi klien yang meminta penanganan perkara sangat khusus dan kompleks di bidang yang belum dikuasainya. Apa tindakan paling profesional?', ['Langsung menerima agar memperoleh pengalaman.', 'Menerima dan berpura-pura menguasai bidang tersebut.', 'Menilai kompetensinya; jika tidak memadai, dapat menolak atau membantu klien mencari profesional yang lebih kompeten.', 'Menerima dengan menjanjikan kemenangan.'], 'C', 'Advokat tidak harus menguasai semua bidang hukum, tetapi harus memahami batas kompetensinya. Menerima perkara di luar kemampuan dapat merugikan klien, misalnya karena kesalahan prosedur, dokumen, atau tenggat waktu.'],
        ['Seorang advokat pernah mewakili Budi dan memperoleh informasi rahasia tentang sengketa tertentu. Kemudian Ahmad meminta advokat itu menangani perkara baru yang berkaitan erat dengan sengketa sebelumnya. Apa yang harus dilakukan advokat?', ['Langsung menerima karena Ahmad adalah klien baru.', 'Menerima selama Ahmad membayar lebih tinggi.', 'Memeriksa kemungkinan konflik kepentingan berdasarkan fakta dan ketentuan etik sebelum menerima perkara.', 'Menggunakan informasi rahasia Budi untuk memenangkan perkara Ahmad.'], 'C', 'Riwayat hubungan profesional dengan klien sebelumnya dapat menimbulkan konflik kepentingan. Advokat harus menjaga kerahasiaan informasi dan tidak boleh menggunakannya secara tidak patut untuk merugikan mantan klien.'],
        ['Dua orang yang kepentingannya saling bertentangan meminta advokat yang sama menangani sengketa yang sama. Persoalan etik yang muncul adalah ...', ['Pelanggaran persyaratan usia.', 'Konflik kepentingan.', 'Persoalan prodeo.', 'Persoalan litigasi.'], 'B', 'Advokat harus mempertimbangkan konflik kepentingan ketika dua klien memiliki kepentingan bertentangan. Ia tidak boleh begitu saja menerima keduanya jika bertentangan dengan kewajiban profesional dan kode etik.'],
        ['Seorang advokat berkemampuan hukum baik, tetapi tidak pernah memperbarui pengetahuannya meski ada perkembangan hukum dan peraturan baru. Prinsip etika apa yang kurang diperhatikan?', ['Kompetensi profesional.', 'Prodeo.', 'Kedudukan penggugat.', 'Kewenangan pengadilan.'], 'A', 'Kompetensi tidak berhenti setelah seseorang diangkat menjadi advokat. Advokat harus terus memperbarui pengetahuan dan meningkatkan keterampilan agar layanan hukumnya berkualitas.'],
        ['Mengapa advokat wajib menjaga kerahasiaan klien?', ['Agar klien tidak mengetahui perkembangan perkara.', 'Karena advokat dapat mengetahui informasi pribadi, dokumen, strategi hukum, dan fakta sensitif milik klien.', 'Agar advokat dapat menyimpan dokumen untuk kepentingan pribadi.', 'Karena semua perkara harus dirahasiakan dari pengadilan.'], 'B', 'Kerahasiaan adalah unsur penting dalam hubungan kepercayaan antara advokat dan klien. Informasi klien harus diperlakukan sesuai kewajiban kerahasiaan yang berlaku.'],
        ['Seorang advokat menjanjikan kepada klien bahwa perkaranya pasti dimenangkan. Bagaimana tindakan tersebut dinilai berdasarkan materi?', ['Benar, karena advokat harus meyakinkan klien.', 'Benar, apabila klien membayar mahal.', 'Tidak tepat, karena advokat tidak seharusnya menjanjikan hasil yang tidak pasti.', 'Tidak masalah karena hasil perkara sepenuhnya ditentukan advokat.'], 'C', 'Putusan pengadilan bergantung pada berbagai faktor hukum dan fakta. Tanggung jawab advokat adalah memberikan layanan profesional, menjelaskan risiko, dan memperjuangkan kepentingan klien, bukan menjamin kemenangan.'],
        ['Seorang advokat diminta klien menyembunyikan dokumen yang relevan dengan perkara. Advokat yang berintegritas seharusnya ...', ['Menyembunyikannya karena kepentingan klien adalah prioritas mutlak.', 'Menjelaskan risiko hukum dan mengambil langkah sesuai hukum serta kode etik.', 'Memusnahkan dokumen tersebut.', 'Menyerahkan dokumen kepada pihak lawan tanpa pertimbangan.'], 'B', 'Advokat bukan sekadar pelaksana keinginan klien. Ia memperjuangkan kepentingan klien dengan cara yang sah dan etis. Integritas berarti tetap berpegang pada prinsip meski ada tekanan.'],
        ['Berikut ini yang paling tepat menggambarkan independensi seorang advokat adalah ...', ['Advokat selalu mengikuti keinginan klien.', 'Advokat bebas melanggar prosedur demi kepentingan klien.', 'Advokat memberikan pertimbangan hukum secara profesional tanpa dipengaruhi kepentingan yang bertentangan.', 'Advokat tidak perlu mempertimbangkan kode etik.'], 'C', 'Independensi berarti advokat mampu menjalankan kewajiban profesional secara objektif dan tidak membiarkan kepentingan lain mengganggu tanggung jawabnya kepada klien.'],
        ['Manakah pernyataan yang paling tepat mengenai tanggung jawab advokat kepada klien?', ['Memenuhi seluruh permintaan klien tanpa pengecualian.', 'Memperjuangkan kepentingan hukum klien secara kompeten, menjelaskan risiko, serta tetap mematuhi hukum dan etika.', 'Menjamin semua perkara akan dimenangkan.', 'Mengutamakan honorarium dibandingkan kepentingan hukum klien.'], 'B', 'Tanggung jawab profesional tidak berarti menuruti seluruh keinginan klien. Advokat harus membantu secara kompeten, jujur, independen, dan bertanggung jawab.'],
        ['Mengapa konflik kepentingan dapat menurunkan kepercayaan masyarakat terhadap profesi advokat?', ['Karena advokat menjadi lebih terkenal.', 'Karena konflik kepentingan dapat membuat advokat tidak objektif dan mengabaikan kepentingan profesional klien.', 'Karena advokat menjadi lebih berpengalaman.', 'Karena semua klien memiliki kepentingan yang sama.'], 'B', 'Masyarakat harus dapat percaya bahwa advokat menjalankan tugas berdasarkan etika profesi. Konflik kepentingan dapat merusak independensi, objektivitas, dan kepercayaan tersebut.'],
        ['Manakah pernyataan yang paling tepat menggambarkan keseluruhan prinsip profesi advokat berdasarkan PDF?', ['Advokat adalah orang yang bertugas memenangkan perkara dengan segala cara.', 'Advokat merupakan profesi yang hanya bekerja di dalam pengadilan.', 'Advokat adalah profesional yang memperjuangkan kepentingan hukum klien secara sah, kompeten, independen, jujur, dan bertanggung jawab.', 'Advokat wajib menerima setiap perkara yang ditawarkan kepadanya.'], 'C', 'Inilah benang merah seluruh materi: advokat bukan hanya pembela klien, tetapi profesional yang memiliki tanggung jawab hukum dan moral.']
      ])
    },
    {
      id: 'etika-profesi-hukum-p8-simulasi',
      title: 'Pertemuan 8: Simulasi ujian 10 soal',
      course: 'Etika Profesi Hukum',
      questions: m([
        ['Advokat sudah berusia 24 tahun, lulus pendidikan hukum, dan lulus ujian profesi. Apa kekurangannya?', ['Belum memenuhi usia minimal', 'Belum memenuhi syarat WNI', 'Belum memenuhi syarat pendidikan', 'Belum memenuhi syarat integritas'], 'A', 'Usia minimal untuk menjadi advokat adalah 25 tahun.'],
        ['Advokat memberikan jasa hukum gratis kepada warga tidak mampu. Istilahnya?', ['Prodeo', 'Pro bono', 'Nonlitigasi', 'Permohonan'], 'B', 'Pro bono adalah jasa hukum cuma-cuma. Prodeo adalah pembebasan biaya perkara.'],
        ['Tergugat memberikan tanggapan terhadap replik. Disebut?', ['Gugatan', 'Jawaban', 'Duplik', 'Somasi'], 'C', 'Duplik adalah tanggapan tergugat terhadap replik penggugat.'],
        ['Advokat pernah memperoleh rahasia dari pihak lawan. Apa yang harus dilakukan sebelum menerima perkara baru?', ['Langsung menerima', 'Memeriksa konflik kepentingan', 'Meminta biaya lebih tinggi', 'Mengabaikan hubungan lama'], 'B', 'Hubungan profesional sebelumnya dapat menimbulkan konflik kepentingan, jadi harus diperiksa lebih dulu.'],
        ['Advokat diminta klien membuat bukti palsu. Prinsip apa yang harus dijaga?', ['Popularitas', 'Honorarium', 'Integritas dan etika', 'Kecepatan kerja'], 'C', 'Advokat tidak boleh memalsukan fakta atau dokumen, meski klien memintanya.'],
        ['Apakah konsultasi hukum otomatis berarti advokat sudah menjadi kuasa klien?', ['Ya, selalu', 'Tidak, keduanya berbeda', 'Ya, jika konsultasinya lama', 'Tidak, advokat tidak boleh berkonsultasi'], 'B', 'Seseorang dapat berkonsultasi tanpa menunjuk advokat sebagai kuasa hukum untuk menangani perkara.'],
        ['Apa urutan tahapan jawab-menjawab perkara perdata?', ['Jawaban–Gugatan–Duplik–Replik', 'Gugatan–Jawaban–Replik–Duplik', 'Gugatan–Replik–Jawaban–Duplik', 'Replik–Gugatan–Jawaban–Duplik'], 'B', 'Gugatan (penggugat), jawaban (tergugat), replik (penggugat), duplik (tergugat).'],
        ['Seseorang belum meminta advokat mewakilinya. Bolehkah advokat langsung menggugat atas namanya?', ['Boleh tanpa batas', 'Boleh jika advokat berpengalaman', 'Tidak, harus ada dasar kewenangan', 'Boleh jika perkara perdata'], 'C', 'Advokat memerlukan dasar hubungan profesional dan kewenangan yang sesuai untuk bertindak atas nama seseorang.'],
        ['Apakah advokat harus menerima perkara di luar kompetensinya?', ['Ya, demi pengalaman', 'Ya, jika dibayar', 'Tidak, dapat menolak atau mencari alternatif yang kompeten', 'Ya, jika klien memaksa'], 'C', 'Advokat harus memahami batas kompetensinya dan dapat menolak atau membantu klien mencari profesional yang lebih kompeten.'],
        ['Apa inti etika profesi advokat?', ['Memenangkan perkara dengan cara apa pun', 'Memperjuangkan kepentingan hukum secara kompeten, independen, jujur, dan bertanggung jawab', 'Mengikuti semua permintaan klien', 'Mengutamakan honorarium'], 'B', 'Advokat memperjuangkan kepentingan klien secara sah, kompeten, independen, jujur, dan bertanggung jawab.']
      ])
    }
  ];
})();
;
/* Bank soal: Etika Profesi Hukum, Modul 1–7 (145 soal). Bentuk: [pertanyaan, [pilihan A–E], huruf jawaban, pembahasan] */
(function () {
  var C = 'Etika Profesi Hukum';
  var m = function (a) { return a.map(function (x) { return { q: x[0], o: x[1], a: x[2], e: x[3] }; }); };
  var bab = [
    ['b1', 'Bab I: Dasar-dasar etika profesi hukum', m([
      ['Secara etimologis, kata etika berasal dari bahasa Yunani Kuno yang berkaitan dengan pengertian berikut, KECUALI ....', ['Kebiasaan', 'Adat', 'Watak', 'Sikap', 'Kekayaan'], 'E', 'Etika berkaitan dengan kebiasaan, adat, watak, dan sikap manusia. Kekayaan bukan bagian dari pengertian etika.'],
      ['Secara istilah, etika merupakan ilmu yang mempelajari ....', ['Hubungan kekuasaan antara pemerintah dan rakyat.', 'Baik dan buruk serta kewajiban moral manusia.', 'Cara memperoleh keuntungan dalam pekerjaan.', 'Hubungan ekonomi dalam masyarakat.', 'Peraturan yang hanya mengatur kehidupan negara.'], 'B', 'Etika mempelajari penilaian baik-buruk sekaligus kewajiban moral yang seharusnya dilakukan manusia.'],
      ['Dua orang mengembalikan dompet yang ditemukan. Orang pertama karena menyadari mengambil hak orang lain adalah salah, orang kedua karena takut dihukum. Apa yang dapat disimpulkan?', ['Keduanya memiliki motivasi moral yang sama.', 'Tindakan orang kedua lebih baik karena takut hukuman.', 'Tindakan lahiriah dapat sama, tetapi motivasi moralnya berbeda.', 'Etika hanya menilai tindakan yang terlihat.', 'Motivasi tidak memiliki hubungan dengan etika.'], 'C', 'Etika memperhatikan tindakan lahiriah sekaligus alasan dan motivasi yang mendasarinya.'],
      ['Berikut yang merupakan contoh kewajiban moral seorang hakim adalah ....', ['Mengutamakan kepentingan pihak yang memberikan hadiah.', 'Memutus perkara berdasarkan hubungan pribadi.', 'Menjatuhkan putusan sesuai keinginan masyarakat tanpa memeriksa fakta.', 'Bersikap adil dan tidak memihak.', 'Mengikuti seluruh keinginan pihak yang berperkara.'], 'D', 'Hakim wajib memeriksa, mengadili, dan memutus perkara secara adil serta tidak memihak.'],
      ['Mengapa kemampuan teknis dalam bidang hukum saja tidak cukup untuk menjadikan seseorang profesional hukum yang baik?', ['Karena kemampuan teknis tidak diperlukan dalam profesi hukum.', 'Karena profesi hukum hanya mengutamakan pengalaman.', 'Karena kemampuan teknis tanpa integritas dapat digunakan untuk melakukan penyimpangan.', 'Karena profesional hukum tidak boleh menguasai peraturan.', 'Karena integritas hanya diperlukan oleh masyarakat umum.'], 'C', 'Keahlian tanpa integritas dapat dipakai untuk memanipulasi bukti atau menyalahgunakan kewenangan.'],
      ['Perbedaan utama etika dan moral menurut kerangka materi modul adalah ....', ['Etika membahas hukum, sedangkan moral membahas ekonomi.', 'Etika memiliki cakupan lebih luas karena mempertimbangkan sikap dan motif, sedangkan moral lebih menekankan tindakan atau sikap lahiriah.', 'Etika hanya berlaku bagi hakim, sedangkan moral berlaku bagi masyarakat.', 'Etika selalu tertulis, sedangkan moral selalu tidak tertulis.', 'Etika dan moral sama sekali tidak memiliki hubungan.'], 'B', 'Moral menekankan perilaku yang tampak; etika juga memeriksa nilai dan motivasi di baliknya.'],
      ['Dalam perspektif Islam, konsep etika dan moral berkaitan erat dengan ....', ['Akhlak', 'Ekonomi', 'Kekuasaan', 'Administrasi', 'Politik praktis'], 'A', 'Akhlak berkaitan dengan karakter dan perilaku manusia: kejujuran, keadilan, amanah, tanggung jawab, serta larangan berbuat zalim.'],
      ['Menurut modul, profesi adalah ....', ['Semua kegiatan yang menghasilkan uang.', 'Pekerjaan yang dilakukan sesekali tanpa keahlian khusus.', 'Pekerjaan yang dilakukan terus-menerus dalam jangka waktu lama dan ditopang pendidikan khusus.', 'Pekerjaan yang hanya dilakukan oleh pegawai negeri.', 'Pekerjaan yang tidak membutuhkan tanggung jawab.'], 'C', 'Profesi memiliki kompetensi, pendidikan atau keahlian tertentu, standar perilaku, dan tanggung jawab profesional.'],
      ['Berikut yang BUKAN merupakan ciri atau syarat profesi menurut modul adalah ....', ['Pendidikan khusus.', 'Memiliki organisasi profesi.', 'Mendapatkan pengakuan.', 'Memiliki kode etik.', 'Bebas menjalankan pekerjaan tanpa aturan.'], 'E', 'Empat ciri profesi: pendidikan khusus, organisasi profesi, pengakuan, dan kode etik.'],
      ['Fungsi utama kode etik dalam suatu profesi adalah ....', ['Memberikan kebebasan tanpa batas kepada anggota.', 'Menentukan besarnya penghasilan anggota.', 'Mengatur hubungan ekonomi antaranggota saja.', 'Menjadi pedoman mengenai perilaku yang wajib dilakukan dan dilarang.', 'Menggantikan seluruh peraturan perundang-undangan.'], 'D', 'Kode etik mengatur standar perilaku profesional: kewajiban, larangan, dan tanggung jawab anggota.'],
      ['Perbedaan mendasar antara hukum dan etika terletak pada ....', ['Hukum mengatur ekonomi, sedangkan etika mengatur politik.', 'Hukum berfokus pada aturan dan kewajiban hukum, sedangkan etika berfokus pada baik-buruk dan tanggung jawab moral.', 'Hukum hanya berlaku bagi pejabat, sedangkan etika hanya berlaku bagi masyarakat.', 'Hukum tidak memiliki sanksi, sedangkan etika memiliki sanksi pidana.', 'Hukum dan etika memiliki sumber dan tujuan yang sepenuhnya sama.'], 'B', 'Hukum bersumber dari konstitusi, undang-undang, dan sumber hukum yang diakui; etika dari nilai moral, prinsip etis, dan standar perilaku.'],
      ['Pernyataan yang paling tepat mengenai hubungan hukum dan etika adalah ....', ['Semua tindakan tidak etis pasti merupakan tindak pidana.', 'Semua tindakan yang legal pasti baik secara moral.', 'Hukum dan etika tidak memiliki hubungan.', 'Tindakan dapat melanggar etika tanpa otomatis menjadi tindak pidana, dan kepatuhan hukum belum tentu menyelesaikan persoalan moral.', 'Etika hanya berlaku apabila hukum tidak mengatur suatu tindakan.'], 'D', 'Hukum dan etika saling berkaitan tetapi tidak identik. Penilaian legalitas berbeda dari penilaian moralitas.'],
      ['Definisi etika profesi hukum menurut modul adalah ....', ['Aturan ekonomi bagi orang yang bekerja di pengadilan.', 'Aturan dan nilai moral yang menjadi pedoman perilaku bagi orang-orang yang bekerja di bidang hukum.', 'Peraturan yang hanya mengatur hubungan hakim dengan pemerintah.', 'Kebebasan profesional untuk melakukan segala tindakan demi kemenangan perkara.', 'Sistem administrasi untuk mengatur penghasilan praktisi hukum.'], 'B', 'Etika profesi hukum menjadi pedoman agar praktisi hukum menjalankan kewenangan dan tanggung jawabnya secara benar.'],
      ['Pasangan profesi dan contoh perilaku etik yang tepat adalah ....', ['Hakim — menerima hadiah dari pihak berperkara.', 'Jaksa — memanipulasi bukti untuk memenangkan perkara.', 'Advokat — menjaga kerahasiaan klien.', 'Polisi — menggunakan kewenangan untuk kepentingan pribadi.', 'Notaris — membuat akta berdasarkan tekanan salah satu pihak.'], 'C', 'Advokat berkewajiban menjaga kerahasiaan klien sesuai kewajiban profesinya.'],
      ['Seorang hakim menerima uang dari salah satu pihak agar memenangkan sengketa tanah. Dampak paling tepat dari tindakan tersebut adalah ....', ['Hanya merugikan pihak yang kalah.', 'Hanya merupakan persoalan pribadi hakim.', 'Tidak memiliki konsekuensi selama putusannya sesuai keinginan pemberi uang.', 'Mengkhianati tanggung jawab moral, melanggar prinsip ketidakberpihakan, dan dapat menimbulkan konsekuensi hukum serta etik.', 'Diperbolehkan selama tidak diketahui masyarakat.'], 'D', 'Penyalahgunaan jabatan merugikan pihak berperkara dan menghancurkan kepercayaan masyarakat terhadap peradilan.'],
      ['Mengapa etika profesi hukum juga penting bagi masyarakat umum?', ['Karena seluruh masyarakat otomatis terikat kode etik hakim dan jaksa.', 'Karena masyarakat menggunakan layanan hukum dan perlu dilindungi dari penyalahgunaan kewenangan.', 'Karena masyarakat berhak mengatur seluruh keputusan hakim.', 'Karena masyarakat menggantikan tugas organisasi profesi.', 'Karena kode etik berlaku sama untuk semua warga negara.'], 'B', 'Masyarakat adalah penerima layanan hukum, tetapi tidak otomatis terikat kode etik profesi hakim atau jaksa.'],
      ['Berikut yang BUKAN termasuk tiga kepentingan utama etika profesi hukum adalah ....', ['Menjaga kepercayaan masyarakat terhadap sistem hukum.', 'Menjadi kompas moral bagi penegak hukum.', 'Menjamin keadilan.', 'Melindungi kepentingan pribadi praktisi hukum di atas masyarakat.', 'Mencegah penyalahgunaan kewenangan.'], 'D', 'Tiga kepentingan utama: menjaga kepercayaan masyarakat, menjadi kompas moral, dan menjamin keadilan.']
    ])],
    ['b2', 'Bab II: Moralitas', m([
      ['Menurut D. Vos sebagaimana dicantumkan dalam modul, moralitas adalah ....', ['Kebiasaan masyarakat yang tidak memiliki aturan.', 'Kaidah atau hukum berupa perintah dan larangan yang mengatur perilaku manusia.', 'Aturan tertulis yang hanya dibuat oleh pemerintah.', 'Kemampuan manusia memperoleh keuntungan.', 'Kesadaran manusia terhadap kekayaan.'], 'B', 'Moralitas mengandung perintah tentang yang seharusnya dilakukan dan larangan tentang yang tidak boleh dilakukan.'],
      ['Manakah pasangan bentuk moralitas yang benar?', ['Perintah — menerima suap; larangan — menjalankan tugas.', 'Perintah — menjalankan tugas dengan jujur; larangan — menerima suap.', 'Perintah — menyalahgunakan jabatan; larangan — menolong masyarakat.', 'Perintah — mengabaikan laporan; larangan — bersikap adil.', 'Perintah — memanipulasi bukti; larangan — menjaga amanah.'], 'B', 'Perintah adalah sesuatu yang wajib dilakukan; larangan adalah sesuatu yang tidak boleh dilakukan.'],
      ['Siapa saja yang memiliki kewajiban menjaga moralitas?', ['Hanya hakim.', 'Hanya pejabat negara.', 'Hanya orang yang bekerja di bidang hukum.', 'Setiap orang, termasuk para profesional hukum.', 'Hanya orang yang berpendidikan tinggi.'], 'D', 'Moralitas adalah tanggung jawab setiap orang; profesional hukum memikul tanggung jawab lebih besar karena kewenangannya memengaruhi hak orang lain.'],
      ['Mengapa semakin besar kewenangan seseorang, semakin besar pula pentingnya integritas?', ['Karena orang yang memiliki jabatan tidak perlu diawasi.', 'Karena kewenangan yang besar dapat berdampak besar terhadap hak, kebebasan, dan kehidupan orang lain.', 'Karena pejabat selalu memiliki kekuasaan mutlak.', 'Karena jabatan menghapus tanggung jawab pribadi.', 'Karena pejabat tidak perlu mengikuti aturan umum.'], 'B', 'Semakin besar kekuasaan, semakin besar potensi penyalahgunaannya, sehingga integritas harus semakin kuat.'],
      ['Berikut yang termasuk faktor internal yang memengaruhi moralitas adalah ....', ['Keluarga, budaya, dan media.', 'Pendidikan, agama, dan masyarakat.', 'Faktor bawaan, faktor individu, dan perkembangan kognitif.', 'Budaya, lingkungan, dan perkembangan teknologi.', 'Agama, teman, dan pendidikan.'], 'C', 'Faktor internal berasal dari dalam diri: faktor bawaan, karakter atau individu, dan perkembangan kognitif.'],
      ['Faktor bawaan dalam pembentukan moralitas memiliki pengertian ....', ['Karakter seseorang yang sepenuhnya ditentukan oleh lingkungan.', 'Karakteristik yang dimiliki sejak awal kehidupan dan dapat memengaruhi kecenderungan perilaku.', 'Kebiasaan yang diperoleh dari media sosial.', 'Pengetahuan yang diperoleh melalui pendidikan tinggi.', 'Aturan yang ditetapkan oleh organisasi profesi.'], 'B', 'Faktor bawaan memengaruhi kecenderungan perilaku, tetapi tidak menentukan moral seseorang secara mutlak.'],
      ['Dua orang mendapat kesempatan yang sama mengambil uang milik orang lain. Yang pertama menolak karena menganggapnya salah, yang kedua mengambilnya demi keuntungan. Perbedaan tersebut terutama menggambarkan faktor ....', ['Budaya.', 'Media.', 'Pendidikan.', 'Individu.', 'Agama.'], 'D', 'Faktor individu berkaitan dengan karakter, kebiasaan, pengendalian diri, dan kecenderungan pribadi.'],
      ['Seorang mahasiswa hukum memahami asas praduga tak bersalah sehingga tahu bahwa seseorang tidak boleh dianggap bersalah hanya karena tuduhan. Kemampuan tersebut berkaitan dengan faktor ....', ['Perkembangan kognitif.', 'Faktor bawaan.', 'Budaya.', 'Media.', 'Lingkungan keluarga.'], 'A', 'Perkembangan kognitif berhubungan dengan kemampuan berpikir, memahami situasi, mempertimbangkan akibat, dan menilai persoalan.'],
      ['Lingkungan yang menganggap suap sebagai hal biasa dapat memengaruhi moralitas seseorang karena ....', ['Lingkungan selalu menentukan seluruh tindakan seseorang.', 'Seseorang dapat terbiasa menganggap tindakan yang salah sebagai sesuatu yang wajar.', 'Suap otomatis menjadi benar jika dilakukan banyak orang.', 'Kebiasaan masyarakat selalu lebih tinggi daripada hukum.', 'Moralitas tidak dipengaruhi lingkungan.'], 'B', 'Lingkungan membentuk cara pandang dan kebiasaan, tetapi kebiasaan yang berkembang tidak otomatis benar.'],
      ['Berikut yang merupakan faktor eksternal moralitas adalah ....', ['Faktor bawaan.', 'Pengendalian diri.', 'Perkembangan kognitif.', 'Karakter individu.', 'Pendidikan.'], 'E', 'Faktor eksternal meliputi lingkungan, budaya, pendidikan, media, dan agama.'],
      ['Mengapa kebiasaan yang sudah berlangsung lama belum tentu dapat dianggap benar?', ['Karena kebiasaan tidak pernah memengaruhi manusia.', 'Karena semua kebiasaan masyarakat pasti melanggar hukum.', 'Karena suatu kebiasaan tetap harus dinilai berdasarkan hukum, moralitas, dan keadilan.', 'Karena kebiasaan hanya berlaku bagi orang tua.', 'Karena budaya tidak memiliki pengaruh terhadap moralitas.'], 'C', 'Contoh: memberi uang kepada petugas untuk mempercepat urusan secara tidak sah tetap bermasalah walau sudah jadi kebiasaan.'],
      ['Perbedaan moralitas dan legalitas yang paling tepat adalah ....', ['Moralitas membahas baik dan buruk, sedangkan legalitas membahas kesesuaian tindakan dengan hukum.', 'Moralitas membahas aturan pemerintah, sedangkan legalitas membahas agama.', 'Moralitas hanya berlaku bagi masyarakat, sedangkan legalitas hanya bagi pejabat.', 'Moralitas selalu tertulis, sedangkan legalitas tidak tertulis.', 'Keduanya tidak memiliki hubungan dengan perilaku manusia.'], 'A', 'Moralitas menilai tindakan berdasarkan prinsip moral; legalitas berdasarkan ketentuan hukum yang berlaku.'],
      ['Seorang pegawai memanfaatkan celah administratif yang secara formal tampak diperbolehkan, tetapi sengaja digunakan untuk merugikan orang lain. Penilaian terhadap kasus tersebut harus ....', ['Hanya memperhatikan keuntungan pegawai.', 'Hanya memperhatikan apakah masyarakat menyukainya.', 'Memeriksa legalitas berdasarkan seluruh ketentuan dan moralitas berdasarkan kejujuran serta keadilan.', 'Menganggap tindakan tersebut otomatis benar karena ada celah aturan.', 'Menganggap semua tindakan administratif tidak memiliki persoalan moral.'], 'C', 'Legalitas dan moralitas adalah dua sudut penilaian yang berbeda. Kepatuhan formal belum tentu menyelesaikan seluruh persoalan etika.'],
      ['Aliran adat menentukan baik dan buruk berdasarkan ....', ['Kekuatan fisik.', 'Kebiasaan masyarakat.', 'Kehendak pemerintah.', 'Keuntungan pribadi.', 'Perkembangan teknologi.'], 'B', 'Aliran adat menilai perilaku berdasarkan adat dan kebiasaan masyarakat, tetapi bukan ukuran mutlak bila bertentangan dengan hukum atau hak asasi manusia.'],
      ['Vitalisme dalam catatan kuliah dikaitkan dengan ....', ['Kehendak Allah.', 'Kegunaan.', 'Kekuatan dalam hidup.', 'Kebiasaan masyarakat.', 'Pendidikan manusia.'], 'C', 'Modul mengaitkan vitalisme dengan kekuatan dalam hidup; teori atau tokohnya belum dijelaskan lebih spesifik.'],
      ['Menurut pendekatan religiusme, sesuatu dinilai baik apabila ....', ['Sesuai dengan kebiasaan masyarakat.', 'Menghasilkan keuntungan terbesar.', 'Sesuai dengan kehendak Allah.', 'Didukung oleh mayoritas masyarakat.', 'Menghasilkan kekuatan politik.'], 'C', 'Religiusme menjadikan kehendak Allah sebagai ukuran kebaikan, termasuk perintah berlaku adil dan larangan berbuat zalim.'],
      ['Pendekatan kegunaan menilai sesuatu sebagai baik apabila ....', ['Bermanfaat atau memiliki kegunaan.', 'Sesuai dengan adat tanpa pengecualian.', 'Menguntungkan pejabat.', 'Sesuai dengan kepentingan pribadi.', 'Dilakukan secara turun-temurun.'], 'A', 'Pendekatan ini mempertimbangkan manfaat suatu tindakan. Modul menulis “bukti litarisme”, yang kemungkinan merujuk pada utilitarianisme, tetapi belum dipastikan.'],
      ['Manakah pasangan istilah Arab dan maknanya yang tepat?', ['الْبِرُّ — keburukan.', 'خَيْرٌ — kebaikan.', 'شَرٌّ — kemuliaan.', 'سُوءٌ — kebaikan.', 'حَسَنَةٌ — kejahatan.'], 'B', 'Kebajikan: الْبِرُّ. Kebaikan: خَيْرٌ, حَسَنَةٌ. Baik: طَيِّبَةٌ. Kemuliaan: كَرِيمًا. Terpuji: مَحْمُودًا. Keburukan: شَرٌّ, سُوءٌ, سَيِّئَةٌ.'],
      ['Perbedaan hukum moralitas dan hukum positif adalah ....', ['Hukum moralitas ditetapkan pemerintah, sedangkan hukum positif ditetapkan keluarga.', 'Hukum moralitas mengatur penilaian benar dan salah secara moral, sedangkan hukum positif adalah hukum yang ditetapkan otoritas berwenang.', 'Hukum moralitas hanya berlaku bagi pejabat.', 'Hukum positif tidak memiliki sanksi.', 'Keduanya merupakan istilah yang sama.'], 'B', 'Hukum moralitas berkaitan dengan pertanggungjawaban moral; hukum positif dengan ketentuan yang berlaku dalam suatu sistem hukum.'],
      ['Seseorang mencuri barang temannya di asrama. Teman-temannya kehilangan kepercayaan dan menegurnya. Contoh tersebut terutama menggambarkan ....', ['Hukum internasional.', 'Hukum administrasi negara.', 'Hukum moralitas.', 'Hukum tata negara.', 'Hukum perdata internasional.'], 'C', 'Hilangnya kepercayaan, teguran, dan kecaman adalah konsekuensi moral atau sosial.'],
      ['Apabila perbuatan pencurian memenuhi unsur tindak pidana berdasarkan peraturan yang berlaku, konsekuensinya termasuk dalam ranah ....', ['Hukum positif.', 'Kebiasaan masyarakat.', 'Hukum moralitas saja.', 'Etika pribadi saja.', 'Budaya lokal.'], 'A', 'Hukum positif memberi konsekuensi hukum menurut ketentuan dan proses hukum yang berlaku. Nomor pasal dalam modul perlu disesuaikan dengan peraturan yang berlaku saat peristiwa terjadi.']
    ])],
    ['b3', 'Bab III: Hati nurani', m([
      ['Hati nurani secara istilah merupakan ....', ['Perasaan senang ketika mendapatkan keuntungan.', 'Kesadaran batin yang menilai apakah suatu tindakan benar atau salah.', 'Kemampuan seseorang menghafal peraturan.', 'Perintah dari atasan.', 'Kebiasaan yang selalu dilakukan masyarakat.'], 'B', 'Hati nurani adalah kesadaran moral dalam diri manusia yang membantu menilai tindakan.'],
      ['Seorang mahasiswa mengikuti ujian tanpa pengawas dan punya kesempatan menyalin jawaban teman, tetapi memilih mengerjakan sendiri karena menyadari menyontek tidak jujur. Perilaku tersebut contoh ....', ['Legalitas.', 'Organisasi.', 'Hati nurani.', 'Kebiasaan.', 'Kekuasaan.'], 'C', 'Kesadaran batin yang mendorong menolak tindakan tidak jujur adalah ilustrasi fungsi hati nurani.'],
      ['Apakah hati nurani manusia selalu benar?', ['Selalu benar karena berasal dari dalam diri manusia.', 'Selalu benar apabila seseorang berpendidikan tinggi.', 'Tidak selalu benar karena dapat dipengaruhi pengetahuan, pengalaman, kebiasaan, dan lingkungan.', 'Selalu salah apabila seseorang bekerja di bidang hukum.', 'Tidak dapat digunakan untuk menilai tindakan.'], 'C', 'Hati nurani harus dibina dan diuji dengan prinsip moral, pengetahuan, serta aturan yang dapat dipertanggungjawabkan.'],
      ['Fungsi hati nurani secara umum dalam modul diibaratkan sebagai ....', ['Senjata hukum.', 'Kompas moral.', 'Peraturan tertulis.', 'Struktur organisasi.', 'Alat ekonomi.'], 'B', 'Seperti kompas yang menunjukkan arah, hati nurani membantu menentukan tindakan yang benar saat menghadapi pilihan sulit.'],
      ['Hakim memeriksa perkara berdasarkan fakta dan hukum, bukan karena tekanan pihak tertentu. Hal tersebut menunjukkan fungsi hati nurani sebagai ....', ['Pedoman moral dan norma.', 'Alat memperoleh kekuasaan.', 'Sarana mencari keuntungan.', 'Alat administrasi.', 'Sarana membangun organisasi.'], 'A', 'Hati nurani membantu profesional hukum menilai apakah tindakannya sesuai dengan tanggung jawab moral.'],
      ['Keadilan yang manusiawi berarti ....', ['Mengabaikan hukum karena merasa kasihan.', 'Mengutamakan perasaan hakim daripada fakta.', 'Melaksanakan hukum dengan tetap memperhatikan martabat manusia dan hak pihak yang terlibat.', 'Membebaskan semua orang yang dituduh melakukan tindak pidana.', 'Mengutamakan kepentingan masyarakat dengan mengabaikan hak individu.'], 'C', 'Seseorang yang diduga melakukan tindak pidana tetap memiliki hak sebagai manusia.'],
      ['Jaksa menyadari bahwa penuntutan tanpa fakta dan alat bukti yang memadai dapat merugikan seseorang. Kesadaran tersebut menunjukkan fungsi hati nurani sebagai ....', ['Membangun kekuasaan.', 'Menyadarkan tanggung jawab moral.', 'Mengatur administrasi.', 'Meningkatkan keuntungan.', 'Menghapus kewajiban hukum.'], 'B', 'Setiap keputusan profesional hukum berdampak pada kehidupan orang lain sehingga harus disertai kesadaran tanggung jawab moral.'],
      ['Advokat mengetahui informasi rahasia klien yang tidak disukainya, tetapi tidak menyebarkannya karena mempertimbangkan kewajiban profesional. Fungsi hati nurani yang ditunjukkan adalah ....', ['Membangun kepercayaan masyarakat.', 'Mendorong kekuasaan.', 'Membimbing tindakan yang tepat.', 'Menghapus tanggung jawab.', 'Mengutamakan kepentingan pribadi.'], 'C', 'Hati nurani membantu memilih tindakan yang tepat saat menghadapi dilema moral dan profesional.'],
      ['Praktisi hukum yang konsisten jujur dan adil lebih mudah mendapatkan kepercayaan masyarakat. Hal tersebut fungsi hati nurani untuk ....', ['Mengembangkan kekayaan.', 'Membangun kepercayaan masyarakat.', 'Menghilangkan peraturan.', 'Memperkuat kekuasaan pribadi.', 'Membatasi hak masyarakat.'], 'B', 'Kepercayaan publik dibangun melalui tindakan yang konsisten dan dapat dipertanggungjawabkan.'],
      ['Sifat hati nurani dalam materi kuliah disebut mutlak otonom. Maksud otonom adalah ....', ['Selalu mengikuti perintah atasan.', 'Bebas melakukan apa saja tanpa batas.', 'Kemampuan mempertimbangkan benar dan salah secara mandiri tanpa sekadar mengikuti tekanan.', 'Tidak membutuhkan pengetahuan moral.', 'Tidak perlu memperhatikan hukum.'], 'C', 'Otonom berarti mandiri dalam pertimbangan moral, bukan berarti keputusan pribadi otomatis benar atau boleh mengabaikan hukum.'],
      ['Mengapa hati nurani disebut benteng pertahanan moral?', ['Karena dapat menghapus seluruh godaan manusia.', 'Karena membantu seseorang menolak tindakan yang bertentangan dengan nilai moral meskipun mendapat tekanan.', 'Karena membuat seseorang tidak membutuhkan aturan.', 'Karena menjamin seseorang tidak pernah melakukan kesalahan.', 'Karena dapat menggantikan hukum positif.'], 'B', 'Benteng moral membantu menghadapi ancaman atasan, godaan uang, kepentingan keluarga, tekanan kelompok, keinginan jabatan, dan ketakutan kehilangan pekerjaan.'],
      ['Hubungan hati nurani dengan etika profesi hukum yang paling tepat adalah ....', ['Hati nurani adalah kompas moral, sedangkan etika profesi hukum adalah peta aturan profesional.', 'Hati nurani adalah hukum positif, sedangkan etika adalah kekuasaan.', 'Hati nurani dan etika profesi hukum tidak memiliki hubungan.', 'Etika profesi hukum hanya berlaku ketika hati nurani tidak berfungsi.', 'Hati nurani dapat menggantikan seluruh kode etik.'], 'A', 'Hati nurani memberi kesadaran moral; etika profesi memberi standar perilaku yang lebih konkret.'],
      ['Berikut yang dapat terjadi apabila penegak hukum tidak menggunakan hati nurani adalah ....', ['Hukum semakin adil secara otomatis.', 'Hilangnya seluruh kewenangan aparat.', 'Hukum tumpul ke atas dan tajam ke bawah, korupsi, mafia peradilan, serta hilangnya kepercayaan publik.', 'Masyarakat semakin percaya kepada penegak hukum.', 'Semua perkara selesai lebih cepat.'], 'C', 'Tanpa kesadaran moral, kewenangan dapat dipakai untuk kepentingan pribadi atau kelompok.'],
      ['Dalam perspektif Islam, hati nurani harus menjadi panduan moral yang selaras dengan ....', ['Kebiasaan masyarakat saja.', 'Al-Qur’an dan Sunnah.', 'Keinginan pribadi.', 'Kepentingan politik.', 'Perintah kelompok.'], 'B', 'Dalam Islam, hati nurani perlu dibina agar selaras dengan Al-Qur’an dan Sunnah.'],
      ['Berikut yang BUKAN termasuk lima peran hati nurani dalam perspektif Islam menurut modul adalah ....', ['Panduan moral.', 'Mendorong kebaikan.', 'Benteng dari kezaliman.', 'Sumber disiplin dan kepatuhan.', 'Sarana memperoleh kekayaan pribadi.'], 'E', 'Lima peran: panduan moral, mendorong kebaikan, benteng dari kezaliman, sumber disiplin dan kepatuhan, serta menjaga hubungan dengan Allah.']
    ])],
    ['b4', 'Bab IV: Organisasi profesi hukum', m([
      ['Istilah organisasi dikaitkan dengan kata Yunani organon yang memiliki arti ....', ['Kekuasaan dan pemerintahan.', 'Alat, anggota badan, atau instrumen.', 'Hukum dan keadilan.', 'Perdagangan dan keuntungan.', 'Pendidikan dan pengetahuan.'], 'B', 'Organisasi menggambarkan kesatuan bagian-bagian yang bekerja sama mencapai tujuan tertentu.'],
      ['Menurut modul, organisasi merupakan ....', ['Sekumpulan orang yang berkumpul tanpa tujuan.', 'Kelompok orang yang bekerja sama secara terstruktur untuk mencapai tujuan bersama.', 'Kelompok yang hanya memiliki seorang pemimpin.', 'Perkumpulan yang selalu bertujuan mencari keuntungan.', 'Kumpulan orang yang tidak memiliki pembagian tugas.'], 'B', 'Organisasi membutuhkan anggota, kerja sama, dan tujuan yang jelas.'],
      ['Tiga unsur utama organisasi adalah ....', ['Kekuasaan, hukum, dan keadilan.', 'Orang, kerja sama, dan tujuan.', 'Pemimpin, uang, dan jabatan.', 'Pendidikan, pekerjaan, dan penghasilan.', 'Peraturan, sanksi, dan hukuman.'], 'B', 'Orang menjadi anggota, kerja sama mengatur kegiatan, tujuan memberi arah.'],
      ['Dalam organisasi mahasiswa, ketua mengoordinasikan kegiatan, sekretaris mengurus administrasi, dan bendahara mengelola keuangan. Ilustrasi tersebut menggambarkan unsur ....', ['Tujuan.', 'Kerja sama.', 'Pengakuan.', 'Kekuasaan negara.', 'Pendidikan khusus.'], 'B', 'Pembagian tugas dan koordinasi antaranggota adalah bentuk kerja sama.'],
      ['Organisasi profesi hukum menurut modul merupakan wadah perkumpulan yang bersifat ....', ['Komersial dan bertujuan membagikan keuntungan.', 'Nirlaba atau nonkomersial dengan anggota yang memiliki keahlian atau profesi yang sama.', 'Politik dan bertujuan mendapatkan kekuasaan.', 'Pemerintahan dan hanya beranggotakan pejabat.', 'Bebas tanpa tujuan organisasi.'], 'B', 'Nirlaba bukan berarti tidak boleh memiliki pemasukan.'],
      ['IKAHI merupakan singkatan dari ....', ['Ikatan Kehakiman Indonesia.', 'Ikatan Hakim Indonesia.', 'Ikatan Hukum Indonesia.', 'Ikatan Kejaksaan Indonesia.', 'Ikatan Advokat Indonesia.'], 'B', 'IKAHI = Ikatan Hakim Indonesia, dibentuk tahun 1953 menurut modul.'],
      ['Tahun pembentukan IKAHI berdasarkan catatan modul adalah ....', ['1945.', '1948.', '1950.', '1953.', '1965.'], 'D', 'Tahun 1953 menurut catatan kuliah.'],
      ['Organisasi yang berkaitan dengan profesi jaksa dalam modul adalah ....', ['IKAHI.', 'INI.', 'PERSAJA.', 'PERADI.', 'POLRI.'], 'C', 'PERSAJA berkaitan dengan profesi jaksa. Modul mencatat Suprapto sebagai ketua pertama.'],
      ['Organisasi profesi notaris yang disebutkan dalam modul adalah ....', ['INI.', 'IKAHI.', 'PERSAJA.', 'PERADI.', 'KAI.'], 'A', 'INI = Ikatan Notaris Indonesia.'],
      ['Berikut yang termasuk organisasi advokat yang disebutkan dalam modul adalah ....', ['IKAHI, INI, dan POLRI.', 'PERSAJA, IKAHI, dan INI.', 'PAI, PERADI, KAI, IKADIN, AAI, IPHI, SPI, dan AKHI.', 'Kejaksaan Negeri dan Kejaksaan Tinggi.', 'POLRI, PERSAJA, dan IKAHI.'], 'C', 'Modul mengaitkan pembahasan organisasi advokat dengan UU Nomor 18 Tahun 2003 tentang Advokat.'],
      ['Pembahasan organisasi advokat dikaitkan dengan peraturan perundang-undangan ....', ['UU Nomor 2 Tahun 2002.', 'UU Nomor 18 Tahun 2003.', 'UU Nomor 4 Tahun 2024.', 'UU Nomor 7 Tahun 2022.', 'UUD 1945 Pasal 1 saja.'], 'B', 'UU Nomor 18 Tahun 2003 adalah undang-undang tentang Advokat.'],
      ['Mengapa POLRI berbeda dari IKAHI dan INI?', ['POLRI adalah organisasi yang tidak memiliki anggota.', 'POLRI adalah institusi negara yang menjalankan fungsi kepolisian, sedangkan IKAHI dan INI adalah organisasi profesi.', 'IKAHI dan INI adalah lembaga negara yang menjalankan fungsi kepolisian.', 'POLRI hanya organisasi sosial.', 'POLRI adalah organisasi advokat.'], 'B', 'Organisasi profesi dan institusi negara memiliki kedudukan, fungsi, dan kewenangan yang berbeda.'],
      ['Berikut yang merupakan fungsi umum organisasi profesi hukum adalah ....', ['Menggantikan seluruh kewenangan pemerintah.', 'Mengembangkan kompetensi anggota dan memperkuat standar profesional.', 'Menentukan seluruh putusan pengadilan.', 'Mengatur kehidupan pribadi masyarakat.', 'Menghapus kode etik profesi.'], 'B', 'Fungsinya meliputi pengembangan kompetensi, pertukaran pengetahuan, pendidikan, kegiatan ilmiah, penguatan standar profesional, dan perlindungan kepentingan profesi sesuai kewenangannya.']
    ])],
    ['b5', 'Bab V: Profesi polisi', m([
      ['Kepolisian menurut modul merupakan aparat negara atau pranata sipil yang bertugas ....', ['Memutus perkara pidana.', 'Membela kepentingan klien di pengadilan.', 'Menjaga keamanan dan ketertiban, menegakkan hukum, serta memberikan perlindungan, pengayoman, dan pelayanan kepada masyarakat.', 'Membuat akta autentik.', 'Menjalankan fungsi penuntutan.'], 'C', 'Fungsi kepolisian: menjaga keamanan, ketertiban, penegakan hukum, perlindungan, pengayoman, dan pelayanan masyarakat.'],
      ['Perbedaan perlindungan, pengayoman, dan pelayanan dalam tugas kepolisian adalah ....', ['Ketiganya tidak memiliki perbedaan.', 'Perlindungan berkaitan dengan keselamatan dan hak, pengayoman memberikan rasa aman, sedangkan pelayanan berkaitan dengan layanan kepolisian sesuai kewenangan.', 'Perlindungan hanya untuk pejabat, pengayoman hanya untuk polisi, dan pelayanan hanya untuk hakim.', 'Perlindungan berkaitan dengan hukuman, pengayoman dengan penuntutan, dan pelayanan dengan putusan.', 'Ketiganya hanya berkaitan dengan administrasi negara.'], 'B', 'Ketiganya saling berkaitan tetapi memiliki penekanan berbeda.'],
      ['Dasar hukum utama kepolisian yang benar menurut koreksi dalam modul adalah ....', ['UU Nomor 2 Tahun 2022.', 'UU Nomor 18 Tahun 2003.', 'UU Nomor 2 Tahun 2002.', 'UU Nomor 4 Tahun 2024.', 'UU Nomor 7 Tahun 2022.'], 'C', 'Modul mengoreksi catatan awal (2022). Yang benar: UU Nomor 2 Tahun 2002 tentang Kepolisian Negara Republik Indonesia.'],
      ['Salah satu persyaratan umum menjadi anggota Polri menurut daftar dalam modul adalah ....', ['Warga negara asing.', 'Berumur minimal 18 tahun saat dilantik.', 'Berpendidikan minimal sarjana hukum.', 'Tidak wajib mengikuti pendidikan pembentukan.', 'Tidak harus setia kepada NKRI.'], 'B', 'Modul mencantumkan usia minimal 18 tahun saat dilantik.'],
      ['Manakah yang TIDAK termasuk delapan persyaratan umum anggota Polri menurut daftar modul?', ['Warga Negara Republik Indonesia.', 'Beriman dan bertakwa kepada Tuhan Yang Maha Esa.', 'Setia kepada NKRI berdasarkan Pancasila dan UUD 1945.', 'Berpendidikan minimal SMA atau sederajat.', 'Wajib memiliki gelar Sarjana Hukum.'], 'E', 'Pendidikan umum yang dicantumkan adalah minimal SMA atau sederajat, bukan Sarjana Hukum.'],
      ['Persyaratan anggota Polri yang berkaitan dengan pembentukan kompetensi dan disiplin adalah ....', ['Memiliki kekayaan pribadi.', 'Lulus pendidikan dan pelatihan pembentukan anggota kepolisian.', 'Memiliki usaha sendiri.', 'Memiliki organisasi politik.', 'Memiliki jabatan pemerintahan sebelumnya.'], 'B', 'Pendidikan dan pelatihan pembentukan memberi bekal pengetahuan, keterampilan, disiplin, dan pemahaman tanggung jawab profesi.'],
      ['Berikut yang termasuk tugas pokok polisi menurut pengelompokan dalam modul adalah ....', ['Memutus perkara dan menjatuhkan hukuman.', 'Memelihara keamanan dan ketertiban masyarakat.', 'Membuat akta autentik.', 'Memberikan pembelaan hukum kepada klien.', 'Menetapkan undang-undang.'], 'B', 'Tugas polisi: memelihara keamanan dan ketertiban, menegakkan hukum, mengayomi, melayani, dan membina masyarakat.'],
      ['Penyuluhan tentang pencegahan penipuan dan bahaya narkotika termasuk kegiatan ....', ['Pembinaan masyarakat.', 'Pemutusan perkara.', 'Penuntutan.', 'Pengadilan.', 'Pembuatan akta.'], 'A', 'Pembinaan masyarakat bertujuan meningkatkan kesadaran hukum dan kepedulian terhadap keamanan.'],
      ['Perbedaan penyelidikan dan penyidikan yang tepat adalah ....', ['Penyelidikan bertujuan menjatuhkan hukuman, sedangkan penyidikan bertujuan membuat putusan.', 'Penyelidikan mencari dan menemukan peristiwa yang diduga tindak pidana, sedangkan penyidikan mencari dan mengumpulkan bukti serta menemukan tersangka.', 'Penyelidikan dilakukan hakim, sedangkan penyidikan dilakukan advokat.', 'Penyelidikan merupakan penuntutan, sedangkan penyidikan merupakan putusan.', 'Keduanya merupakan istilah yang sama.'], 'B', 'Penyelidikan adalah tahap awal menentukan apakah peristiwa dapat dilanjutkan ke penyidikan; penyidikan berfokus mengumpulkan bukti dan membuat terang tindak pidana.'],
      ['Masyarakat melaporkan dugaan pencurian. Polisi melakukan tindakan awal untuk memastikan apakah benar ada peristiwa yang diduga tindak pidana. Tahap tersebut disebut ....', ['Penuntutan.', 'Persidangan.', 'Penyelidikan.', 'Pemutusan perkara.', 'Pelaksanaan putusan.'], 'C', 'Penyelidikan adalah tahap awal mencari dan menemukan peristiwa yang diduga tindak pidana.'],
      ['Setelah ditemukan dasar bahwa suatu peristiwa diduga tindak pidana, polisi mengumpulkan bukti untuk membuat terang perkara. Tahap ini disebut ....', ['Pengayoman.', 'Penyidikan.', 'Penuntutan.', 'Pengadilan.', 'Pembelaan.'], 'B', 'Penyidikan berfokus pada pengumpulan bukti dan menemukan tersangka sesuai hukum acara pidana.'],
      ['Pernyataan yang benar mengenai tugas polisi adalah ....', ['Polisi hanya bertugas menangkap pelaku kejahatan.', 'Polisi hanya bertugas mengatur lalu lintas.', 'Polisi memiliki tugas pencegahan, pelayanan, perlindungan, pembinaan, dan penegakan hukum.', 'Polisi memiliki kewenangan memutus perkara.', 'Polisi bertugas menggantikan hakim.'], 'C', 'Fungsi kepolisian lebih luas daripada penangkapan pelaku kejahatan.'],
      ['Kode etik profesi Polri merupakan pedoman mengenai ....', ['Sikap, perilaku, dan ucapan anggota Polri.', 'Penghasilan anggota Polri saja.', 'Hubungan ekonomi masyarakat.', 'Putusan hakim.', 'Pekerjaan advokat.'], 'A', 'Kode etik mengatur perilaku anggota Polri saat menjalankan tugas, menggunakan kewenangan, dan dalam kehidupan sehari-hari.'],
      ['Dasar pengaturan kode etik profesi Polri dalam modul adalah ....', ['UU Nomor 18 Tahun 2003.', 'Perpol Nomor 7 Tahun 2022.', 'UU Nomor 2 Tahun 2002.', 'Peraturan Kejaksaan Nomor 4 Tahun 2024.', 'UU Nomor 1 Tahun 1945.'], 'B', 'Perpol Nomor 7 Tahun 2022 mengatur Kode Etik Profesi dan Komisi Kode Etik Polri.'],
      ['Kode etik Polri dibagi menjadi empat kelompok utama, yaitu ....', ['Etika politik, ekonomi, sosial, dan budaya.', 'Etika kenegaraan, kelembagaan, kemasyarakatan, dan kepribadian.', 'Etika pidana, perdata, tata negara, dan administrasi.', 'Etika pribadi, keluarga, pendidikan, dan pekerjaan.', 'Etika organisasi, pengadilan, kejaksaan, dan advokat.'], 'B', 'Keempat kelompok memiliki fokus berbeda dan harus dipahami terpisah.'],
      ['Seorang anggota Polri wajib setia kepada NKRI, menjaga keutuhan wilayah, dan memelihara persatuan bangsa. Kewajiban tersebut termasuk ....', ['Etika kelembagaan.', 'Etika kepribadian.', 'Etika kemasyarakatan.', 'Etika kenegaraan.', 'Etika organisasi.'], 'D', 'Etika kenegaraan mengatur tanggung jawab terhadap negara, konstitusi, dan persatuan bangsa.'],
      ['Anggota Polri harus menjaga citra institusi, menjalankan perintah kedinasan yang sah, serta menyelesaikan tugas dengan profesional. Hal tersebut termasuk ....', ['Etika kenegaraan.', 'Etika kelembagaan.', 'Etika kepribadian.', 'Etika kemasyarakatan.', 'Etika keluarga.'], 'B', 'Etika kelembagaan berkaitan dengan tanggung jawab terhadap institusi Polri, profesionalitas, dan kedisiplinan.'],
      ['Seorang anggota polisi mengabaikan laporan masyarakat karena pelapor berasal dari keluarga miskin. Pelanggaran tersebut terutama berkaitan dengan ....', ['Etika kenegaraan.', 'Etika kelembagaan.', 'Etika kemasyarakatan.', 'Etika kepribadian.', 'Etika organisasi.'], 'C', 'Etika kemasyarakatan menekankan penghormatan terhadap harkat dan martabat manusia serta kesetaraan warga negara di hadapan hukum.'],
      ['Seorang anggota polisi dituntut memiliki sifat jujur, disiplin, adil, humanis, dan menaati norma hukum serta agama. Ketentuan tersebut berkaitan dengan ....', ['Etika kenegaraan.', 'Etika kemasyarakatan.', 'Etika kelembagaan.', 'Etika kepribadian.', 'Etika administrasi.'], 'D', 'Etika kepribadian berhubungan dengan karakter, perilaku pribadi, dan integritas.'],
      ['Seorang polisi mendapat perintah atasan untuk menyembunyikan bukti pelanggaran. Sikap yang benar berdasarkan prinsip etika kelembagaan adalah ....', ['Harus mengikuti karena semua perintah atasan wajib dilaksanakan.', 'Menyembunyikan bukti selama tidak diketahui masyarakat.', 'Tidak boleh mengikuti perintah yang jelas bertentangan dengan hukum dan harus bertindak sesuai prosedur.', 'Mengabaikan seluruh tugas kedinasan.', 'Menghapus bukti tersebut agar tidak menjadi masalah.'], 'C', 'Kewajiban menaati perintah kedinasan tidak berarti wajib mengikuti perintah yang melanggar hukum.'],
      ['Modul membagi sanksi pelanggaran kode etik polisi menjadi ....', ['Dua kategori.', 'Tiga kategori: ringan, sedang, dan berat.', 'Empat kategori.', 'Lima kategori.', 'Enam kategori.'], 'B', 'Tingkat pelanggaran dibedakan berdasarkan keseriusan dan ketentuan yang berlaku.'],
      ['PTDH merupakan singkatan dari ....', ['Pemberhentian Tugas Dengan Hak.', 'Pengawasan Terhadap Disiplin Hukum.', 'Pemberhentian Tidak Dengan Hormat.', 'Penindakan Terhadap Hakim.', 'Penegakan Tugas dan Hukum.'], 'C', 'PTDH adalah sanksi berat berupa Pemberhentian Tidak Dengan Hormat.'],
      ['Berikut yang dapat menjadi sumber informasi dugaan pelanggaran kode etik polisi adalah ....', ['Laporan masyarakat.', 'Temuan dalam pemeriksaan.', 'Informasi media massa.', 'Laporan pihak terkait.', 'Semua jawaban benar.'], 'E', 'Keempatnya dapat menjadi sumber informasi, tetapi belum otomatis membuktikan seseorang bersalah.']
    ])],
    ['b6', 'Bab VI: Profesi kejaksaan', m([
      ['Menurut catatan sejarah dalam modul, profesi yang berkaitan dengan jaksa telah dikenal sejak masa ....', ['Kerajaan Sriwijaya.', 'Kerajaan Majapahit.', 'Kerajaan Mataram Islam.', 'Masa reformasi.', 'Masa Orde Baru.'], 'B', 'Modul menyebut masa Majapahit dan istilah diaksa serta adiaksa yang dikaitkan dengan Patih Gajah Mada.'],
      ['Kejaksaan secara resmi menjadi bagian dari negara Republik Indonesia sejak ....', ['17 Agustus 1945.', '1 Juni 1945.', '10 November 1945.', '18 Agustus 1945.', '27 Desember 1949.'], 'A', 'Modul membedakan sejarah awal fungsi yang menyerupai jaksa pada masa Majapahit dengan keberadaan kejaksaan dalam struktur negara RI sejak kemerdekaan.'],
      ['Apakah setiap orang yang bekerja di lingkungan kejaksaan otomatis disebut jaksa?', ['Ya, karena semua pegawai kejaksaan memiliki kewenangan penuntutan.', 'Ya, karena seluruh pegawai kejaksaan memiliki jabatan yang sama.', 'Tidak, karena status jaksa melekat pada jabatan dan kewenangan tertentu berdasarkan hukum.', 'Tidak, karena jaksa hanya bekerja di pengadilan.', 'Ya, apabila pegawai tersebut sudah bekerja lebih dari satu tahun.'], 'C', 'Tidak semua pegawai kejaksaan memiliki status atau kewenangan sebagai jaksa.'],
      ['Perbedaan jaksa dan kejaksaan adalah ....', ['Jaksa adalah institusi, sedangkan kejaksaan adalah individu.', 'Jaksa adalah pejabat yang memiliki kewenangan tertentu, sedangkan kejaksaan adalah institusi yang menjalankan fungsi dan kewenangan kejaksaan.', 'Keduanya merupakan istilah yang sama.', 'Jaksa adalah organisasi profesi, sedangkan kejaksaan adalah organisasi advokat.', 'Jaksa adalah hakim, sedangkan kejaksaan adalah pengadilan.'], 'B', 'Jaksa adalah individu dalam jabatan tertentu; kejaksaan adalah lembaga atau institusi.'],
      ['Pendidikan minimal yang dicantumkan dalam persyaratan menjadi jaksa menurut modul adalah ....', ['SMA.', 'Diploma.', 'Sarjana Hukum.', 'Magister Hukum.', 'Doktor Hukum.'], 'C', 'Modul mencantumkan pendidikan minimal Sarjana Hukum.'],
      ['Rentang usia menjadi jaksa yang dicantumkan dalam catatan kuliah adalah ....', ['18–25 tahun.', '20–30 tahun.', '21–40 tahun.', '25–35 tahun.', '30–45 tahun.'], 'D', 'Angka 25–35 tahun adalah isi catatan kuliah; persyaratan usia harus diperiksa kembali pada ketentuan rekrutmen yang berlaku.'],
      ['Berikut yang BUKAN termasuk delapan persyaratan menjadi jaksa dalam catatan modul adalah ....', ['Warga Negara Indonesia.', 'Bertakwa kepada Tuhan Yang Maha Esa.', 'Setia kepada Pancasila dan UUD 1945.', 'Sehat jasmani dan rohani.', 'Tidak perlu memiliki integritas dan perilaku baik.'], 'E', 'Modul justru mensyaratkan integritas, kewibawaan, kejujuran, keadilan, dan perilaku tidak tercela.'],
      ['P3J merupakan singkatan dari ....', ['Pendidikan dan Pelatihan Pembentukan Jaksa.', 'Pengawasan dan Pemeriksaan Perkara Jaksa.', 'Pendidikan dan Pengembangan Jabatan.', 'Pelatihan dan Pengawasan Peradilan.', 'Pembentukan Pengadilan dan Penuntutan.'], 'A', 'P3J membentuk calon jaksa agar memiliki mental, disiplin, pengetahuan, dan keterampilan yang dibutuhkan.'],
      ['Menurut catatan kuliah, durasi P3J adalah ....', ['Dua minggu.', 'Satu bulan.', 'Dua bulan.', 'Empat bulan.', 'Satu tahun.'], 'D', 'Modul mencatat empat bulan, lalu dilanjutkan sumpah atau janji jabatan setelah lulus. Durasi ini perlu diverifikasi terhadap ketentuan resmi terkini.'],
      ['Berikut yang merupakan tugas jaksa dalam bidang pidana menurut modul adalah ....', ['Memutus perkara pidana.', 'Membuat undang-undang pidana.', 'Melakukan penuntutan dan melaksanakan putusan pengadilan yang telah berkekuatan hukum tetap.', 'Menjadi pembela bagi seluruh terdakwa.', 'Melakukan penyelidikan sebagai satu-satunya tugas utama.'], 'C', 'Jaksa menjalankan fungsi penuntutan dan pelaksanaan putusan. Jaksa bukan hakim yang memeriksa, mengadili, dan memutus.'],
      ['Dalam proses peradilan pidana, urutan peran polisi, jaksa, dan hakim yang paling tepat adalah ....', ['Polisi memutus, jaksa menyidik, hakim menuntut.', 'Polisi menyidik, jaksa menuntut, hakim memeriksa, mengadili, dan memutus.', 'Polisi menuntut, jaksa memutus, hakim menyidik.', 'Polisi mengadili, jaksa membela, hakim menyelidiki.', 'Ketiganya memiliki tugas yang sama.'], 'B', 'Ketiga profesi memiliki kewenangan yang berbeda dalam sistem peradilan pidana.']
    ])],
    ['b7', 'Bab VII: Etika profesi jaksa', m([
      ['Etika profesi jaksa merupakan ....', ['Kebebasan jaksa melakukan tindakan tanpa batas.', 'Pedoman perilaku profesi dan aturan moral yang wajib dipatuhi jaksa dalam menjalankan tugas, menjaga kehormatan jabatan, serta kehidupan bermasyarakat.', 'Aturan yang hanya berlaku ketika jaksa berada di pengadilan.', 'Pedoman untuk mendapatkan keuntungan pribadi.', 'Peraturan yang hanya mengatur hubungan jaksa dengan hakim.'], 'B', 'Tanggung jawab etik jaksa tidak hanya saat bekerja, tetapi juga terkait kehormatan jabatan dan perilaku dalam masyarakat.'],
      ['Dasar pengaturan etika profesi jaksa yang disebutkan dalam modul adalah ....', ['Perpol Nomor 7 Tahun 2022.', 'UU Nomor 18 Tahun 2003.', 'Peraturan Kejaksaan Republik Indonesia Nomor 4 Tahun 2024.', 'UU Nomor 2 Tahun 2002.', 'Peraturan Pemerintah Nomor 2 Tahun 1945.'], 'C', 'Peraturan Kejaksaan Nomor 4 Tahun 2024, terdiri atas 13 bab dan 101 pasal.'],
      ['Berikut yang BUKAN merupakan fungsi etika profesi jaksa menurut modul adalah ....', ['Pedoman perilaku.', 'Menjaga martabat dan kehormatan profesi.', 'Meningkatkan integritas dan profesionalisme.', 'Mewujudkan penegakan hukum yang adil.', 'Memberikan kebebasan menyalahgunakan jabatan.'], 'E', 'Enam fungsi: pedoman perilaku, menjaga martabat profesi, meningkatkan integritas dan profesionalisme, mewujudkan penegakan hukum yang adil, membangun kepercayaan publik, dan dasar pemberian sanksi.'],
      ['Integritas dalam profesi jaksa merupakan ....', ['Kemampuan memenangkan seluruh perkara.', 'Keselarasan antara nilai yang diyakini, perkataan, dan tindakan.', 'Kemampuan memperoleh keuntungan dari jabatan.', 'Kemampuan memengaruhi hakim.', 'Ketaatan terhadap seluruh perintah atasan tanpa pengecualian.'], 'B', 'Integritas berarti konsisten antara apa yang diyakini, diucapkan, dan dilakukan.'],
      ['Seorang jaksa mengatakan menolak korupsi, lalu benar-benar menolak uang yang ditawarkan untuk memengaruhi perkara. Perilaku tersebut menunjukkan ....', ['Kebijaksanaan saja.', 'Profesionalitas saja.', 'Integritas.', 'Kekuasaan.', 'Legalitas saja.'], 'C', 'Ada kesesuaian antara nilai yang diucapkan dan tindakan nyata.'],
      ['Berikut yang termasuk empat kewajiban dalam prinsip integritas adalah ....', ['Setia kepada Pancasila dan UUD 1945, taat peraturan, menjaga martabat profesi, serta memberikan layanan hukum profesional.', 'Menerima hadiah, menjaga kekayaan, merangkap pengusaha, dan menggunakan barang bukti.', 'Mengutamakan kepentingan keluarga, menerima suap, dan menghindari tanggung jawab.', 'Memanipulasi bukti, menolak perintah sah, dan mengabaikan sumpah jabatan.', 'Menyebarkan informasi rahasia dan memanfaatkan jabatan.'], 'A', 'Empat kewajiban integritas menekankan kesetiaan kepada negara, kepatuhan hukum, kehormatan profesi, dan layanan hukum profesional.'],
      ['Berikut yang termasuk larangan dalam prinsip integritas adalah ....', ['Memberikan layanan hukum profesional.', 'Mematuhi peraturan perundang-undangan.', 'Meminta atau menerima hadiah yang berkaitan dengan jabatan secara melawan hukum.', 'Menjaga martabat profesi.', 'Menjunjung tinggi Pancasila.'], 'C', 'Larangan integritas: menyalahgunakan barang bukti atau barang milik negara, meminta atau menerima hadiah terkait jabatan, pungutan melawan hukum, dan merangkap pengusaha dalam cakupan larangan yang berlaku.'],
      ['Seorang jaksa menggunakan kendaraan yang merupakan barang bukti sebagai kendaraan pribadinya. Perbuatan tersebut termasuk pelanggaran prinsip ....', ['Kebijaksanaan.', 'Integritas.', 'Profesionalitas saja.', 'Etika kemasyarakatan.', 'Etika kenegaraan.'], 'B', 'Penyalahgunaan barang bukti dan barang milik negara adalah larangan yang berkaitan dengan integritas.'],
      ['Seorang jaksa meminta uang kepada masyarakat untuk mempercepat proses pelayanan tanpa dasar hukum. Perbuatan tersebut termasuk ....', ['Kewajiban profesional.', 'Bentuk pengabdian.', 'Pungutan secara melawan hukum.', 'Bentuk kebijaksanaan.', 'Bentuk pembinaan masyarakat.'], 'C', 'Jaksa dilarang meminta pungutan yang tidak memiliki dasar hukum.'],
      ['Profesionalitas adalah ....', ['Kemampuan memperoleh jabatan tinggi.', 'Menjalankan pekerjaan sesuai standar profesi, kompetensi, tanggung jawab, dan ketentuan yang berlaku.', 'Kemampuan menghindari seluruh tugas yang sulit.', 'Kemampuan mengikuti seluruh keinginan masyarakat.', 'Kemampuan memenangkan perkara dengan segala cara.'], 'B', 'Profesionalitas berkaitan dengan pelaksanaan pekerjaan secara kompeten, cermat, objektif, dan bertanggung jawab.'],
      ['Perbedaan integritas dan profesionalitas yang tepat adalah ....', ['Integritas berhubungan dengan kejujuran dan keteguhan prinsip, sedangkan profesionalitas berkaitan dengan pelaksanaan tugas sesuai standar dan tanggung jawab.', 'Integritas berhubungan dengan kekayaan, sedangkan profesionalitas dengan kekuasaan.', 'Integritas hanya berlaku di luar kantor, sedangkan profesionalitas hanya di dalam kantor.', 'Keduanya memiliki arti yang sama.', 'Integritas berkaitan dengan organisasi, sedangkan profesionalitas dengan politik.'], 'A', 'Integritas: apakah jujur dan memegang prinsip. Profesionalitas: apakah menjalankan tugas dengan standar yang benar.'],
      ['Berikut yang termasuk empat kewajiban dalam prinsip profesionalitas adalah ....', ['Menjunjung kehormatan profesi, sumpah jabatan, menjalankan tugas sesuai peraturan, dan menolak perintah atasan yang bertentangan dengan hukum atau kode etik.', 'Menerima hadiah, menggunakan barang bukti, dan melakukan pungutan.', 'Mengutamakan kepentingan pribadi dan mengabaikan aturan.', 'Menyebarkan rahasia perkara dan mengubah alat bukti.', 'Menghindari tanggung jawab dan menolak seluruh perintah atasan.'], 'A', 'Keempat kewajiban tersebut adalah inti profesionalitas dalam modul.'],
      ['Seorang jaksa diperintah atasannya menggunakan dokumen yang diketahui telah dimanipulasi sebagai dasar penuntutan. Sikap yang benar adalah ....', ['Menggunakan dokumen karena berasal dari atasan.', 'Menggunakan dokumen selama perkara segera selesai.', 'Menolak perintah yang bertentangan dengan hukum atau kode etik dan menyikapinya sesuai prosedur.', 'Mengubah dokumen agar terlihat benar.', 'Mengabaikan seluruh aturan profesi.'], 'C', 'Perintah kedinasan hanya wajib dilaksanakan jika sah. Profesionalitas menuntut jaksa memahami batas kewenangan.'],
      ['Berikut yang merupakan larangan dalam prinsip profesionalitas adalah ....', ['Memeriksa perkara secara cermat.', 'Menjunjung sumpah jabatan.', 'Menggunakan alat bukti yang diketahui atau patut diduga telah direkayasa atau diperoleh secara melawan hukum.', 'Melaksanakan tugas sesuai kewenangan.', 'Menjaga kehormatan profesi.'], 'C', 'Penggunaan bukti yang direkayasa, diubah, dirusak, atau diperoleh melawan hukum adalah pelanggaran profesionalitas.'],
      ['Seorang jaksa menuntut seseorang karena dendam pribadi tanpa fakta dan alat bukti yang cukup. Tindakan tersebut disebut ....', ['Kebijaksanaan.', 'Penuntutan dengan iktikad buruk.', 'Integritas.', 'Pengayoman.', 'Pembinaan.'], 'B', 'Penuntutan harus berdasarkan fakta dan bukti yang memadai, bukan kepentingan atau niat pribadi yang tidak patut.'],
      ['Kebijaksanaan dalam profesi jaksa merupakan kemampuan ....', ['Mengabaikan peraturan berdasarkan perasaan pribadi.', 'Mempertimbangkan tindakan secara matang dengan memperhatikan tanggung jawab, akibat, kepatutan, dan kepentingan yang relevan.', 'Mengutamakan keuntungan pribadi.', 'Mengikuti tekanan masyarakat tanpa pertimbangan.', 'Menghindari seluruh keputusan yang sulit.'], 'B', 'Kebijaksanaan berarti mengambil tindakan secara matang tanpa mengabaikan batas hukum dan tanggung jawab profesi.'],
      ['Berikut yang termasuk kewajiban dalam prinsip kebijaksanaan adalah ....', ['Memamerkan kekayaan dan kemewahan.', 'Menggunakan media sosial tanpa batas.', 'Menerapkan gaya hidup tidak berlebihan dan bijaksana dalam menggunakan media sosial.', 'Mengungkap seluruh informasi perkara kepada publik.', 'Mengikuti seluruh tren media sosial.'], 'C', 'Dua kewajiban: gaya hidup tidak berlebihan dan kebijaksanaan dalam menggunakan media sosial.'],
      ['Seorang jaksa mengunggah informasi rahasia mengenai perkara yang sedang ditanganinya ke media sosial. Tindakan tersebut bertentangan dengan prinsip ....', ['Integritas saja.', 'Profesionalitas saja.', 'Kebijaksanaan.', 'Organisasi.', 'Etika kenegaraan.'], 'C', 'Jaksa harus mempertimbangkan dampak unggahan terhadap proses hukum, informasi yang dilindungi, dan kehormatan jabatan.'],
      ['Manakah yang termasuk larangan dalam prinsip kebijaksanaan menurut modul?', ['Memeriksa bukti secara teliti.', 'Menjaga kehormatan jabatan.', 'Memamerkan gaya hidup, kekayaan, atau kemewahan secara berlebihan.', 'Mematuhi sumpah jabatan.', 'Menolak suap.'], 'C', 'Larangan juga mencakup tidak menghormati norma agama, kesusilaan, kesopanan, dan adat istiadat yang hidup dalam masyarakat.'],
      ['Perbedaan utama antara tiga prinsip etika profesi jaksa adalah ....', ['Integritas = kompetensi; profesionalitas = kekayaan; kebijaksanaan = kekuasaan.', 'Integritas = benar dalam prinsip; profesionalitas = benar dalam menjalankan tugas; kebijaksanaan = matang dalam bertindak.', 'Integritas = hukum; profesionalitas = agama; kebijaksanaan = budaya.', 'Integritas = organisasi; profesionalitas = politik; kebijaksanaan = ekonomi.', 'Ketiganya sama-sama berarti kejujuran.'], 'B', 'Integritas: kejujuran. Profesionalitas: kompetensi. Kebijaksanaan: pertimbangan.'],
      ['Modul membagi pelanggaran kode etik jaksa menjadi ....', ['Dua kategori.', 'Tiga kategori: ringan, sedang, dan berat.', 'Empat kategori.', 'Lima kategori.', 'Enam kategori.'], 'B', 'Kategori dibedakan berdasarkan tingkat keseriusan dan ketentuan yang berlaku.'],
      ['Berikut yang merupakan contoh pelanggaran ringan menurut modul adalah ....', ['Korupsi.', 'Gratifikasi.', 'Terlambat masuk kerja tanpa alasan yang sah.', 'Menggunakan bukti yang direkayasa.', 'Menerima uang untuk memengaruhi perkara.'], 'C', 'Contoh ringan: terlambat masuk, pulang lebih awal, tidak mengikuti upacara atau apel, serta mangkir tanpa alasan sah dalam keadaan yang disebutkan modul.'],
      ['Contoh sanksi yang dicantumkan untuk pelanggaran ringan adalah ....', ['Pemberhentian tidak dengan hormat.', 'Penjara.', 'Teguran lisan atau tertulis.', 'Pemberhentian dengan hak pensiun.', 'Pencabutan kewarganegaraan.'], 'C', 'Sanksi ringan dalam contoh modul berupa teguran lisan atau tertulis.'],
      ['Berikut yang merupakan contoh pelanggaran sedang menurut modul adalah ....', ['Tidak profesional dalam menangani perkara atau sering tidak menghadiri persidangan tanpa alasan.', 'Terlambat masuk kerja satu kali.', 'Menerima uang untuk memenangkan perkara.', 'Korupsi.', 'Gratifikasi yang memenuhi unsur pelanggaran berat.'], 'A', 'Pelanggaran sedang dapat berupa ketidakprofesionalan, pertemuan tidak resmi dengan pihak terkait perkara, dan ketidakhadiran berulang di persidangan tanpa alasan.'],
      ['Contoh sanksi pelanggaran sedang menurut modul adalah ....', ['Teguran lisan saja.', 'Penundaan kenaikan gaji berkala, penundaan kenaikan pangkat, atau penurunan pangkat untuk jangka waktu tertentu.', 'Pemberhentian tidak dengan hormat saja.', 'Hukuman penjara seumur hidup.', 'Pencabutan seluruh hak warga negara.'], 'B', 'Sanksi sedang memiliki konsekuensi administratif atau etik yang lebih serius daripada teguran.'],
      ['Korupsi dan gratifikasi dalam pengelompokan modul merupakan contoh pelanggaran ....', ['Ringan.', 'Sedang.', 'Berat.', 'Administratif biasa.', 'Tidak termasuk pelanggaran etik.'], 'C', 'Korupsi dan gratifikasi dicantumkan sebagai contoh pelanggaran berat.'],
      ['Contoh sanksi pelanggaran berat menurut modul adalah ....', ['Teguran lisan.', 'Teguran tertulis.', 'Penundaan kenaikan gaji berkala.', 'Pemberhentian dengan hak pensiun dan PTDH.', 'Peringatan informal.'], 'D', 'Modul mencantumkan pemberhentian dengan hak pensiun dan Pemberhentian Tidak Dengan Hormat.'],
      ['Seorang jaksa bertemu secara tidak resmi dengan pihak yang berkaitan dengan perkara yang sedang ditanganinya. Mengapa hal tersebut dapat menjadi masalah etik?', ['Karena seluruh pertemuan sosial otomatis dilarang.', 'Karena dapat menciptakan konflik kepentingan atau menimbulkan keraguan terhadap objektivitas penanganan perkara.', 'Karena jaksa tidak boleh berkomunikasi dengan masyarakat.', 'Karena jaksa hanya boleh bertemu hakim.', 'Karena seluruh komunikasi harus dilakukan melalui media sosial.'], 'B', 'Pertemuan perlu dinilai dari tujuan, konteks, aturan, dan keadaan. Tidak semua pertemuan di luar jam kerja otomatis pelanggaran.']
    ])],
    ['kasus', 'Studi kasus dan analisis', m([
      ['Seorang polisi menerima uang agar laporan tindak pidana seseorang tidak diproses. Pelanggaran tersebut paling tepat dikaitkan dengan ....', ['Etika kemasyarakatan dan integritas.', 'Etika kepribadian saja.', 'Etika kenegaraan saja.', 'Organisasi profesi.', 'Kebijaksanaan dalam media sosial.'], 'A', 'Polisi mengabaikan pelayanan masyarakat dan memakai kewenangan untuk keuntungan pribadi.'],
      ['Seorang hakim memutus perkara berdasarkan hubungan keluarga dengan salah satu pihak, meskipun bukti menunjukkan pihak tersebut bersalah. Konsep yang paling jelas dilanggar adalah ....', ['Prinsip keadilan dan ketidakberpihakan.', 'Prinsip organisasi.', 'Prinsip pengembangan kompetensi.', 'Prinsip pelayanan administrasi.', 'Prinsip kebijaksanaan media sosial.'], 'A', 'Hakim harus memutus berdasarkan fakta dan hukum, bukan hubungan pribadi atau kepentingan keluarga.'],
      ['Seorang advokat membocorkan strategi hukum kliennya kepada pihak lawan karena mendapat bayaran lebih besar. Tindakan tersebut terutama melanggar ....', ['Kewajiban menjaga kerahasiaan klien.', 'Kewajiban melakukan penuntutan.', 'Kewajiban memutus perkara.', 'Kewajiban menjaga keamanan masyarakat.', 'Kewajiban melaksanakan putusan pengadilan.'], 'A', 'Menerima uang untuk membocorkan informasi adalah pengkhianatan terhadap kepercayaan klien.'],
      ['Seorang jaksa sangat menguasai teori hukum, tetapi tidak pernah memeriksa bukti dengan cermat sebelum mengajukan penuntutan. Prinsip yang paling jelas bermasalah adalah ....', ['Integritas saja.', 'Profesionalitas.', 'Organisasi.', 'Etika kenegaraan.', 'Etika kelembagaan polisi.'], 'B', 'Profesionalitas berarti menerapkan pengetahuan dengan cermat, objektif, dan sesuai prosedur.'],
      ['Seorang jaksa menolak suap, memeriksa seluruh bukti secara teliti, dan berhati-hati menyampaikan informasi perkara di media sosial. Ketiganya secara berurutan mencerminkan ....', ['Kebijaksanaan, integritas, profesionalitas.', 'Integritas, profesionalitas, kebijaksanaan.', 'Profesionalitas, kebijaksanaan, integritas.', 'Integritas, kebijaksanaan, profesionalitas.', 'Profesionalitas, integritas, kebijaksanaan.'], 'B', 'Menolak suap = integritas. Memeriksa bukti teliti = profesionalitas. Berhati-hati di media sosial = kebijaksanaan.'],
      ['Seorang petugas menganggap menerima uang dari pihak berperkara hal biasa karena seluruh rekannya melakukan hal yang sama, bahkan tidak merasa bersalah. Kesimpulan yang tepat adalah ....', ['Tindakan tersebut benar karena sudah menjadi kebiasaan.', 'Hati nurani tidak selalu benar dan dapat dipengaruhi lingkungan.', 'Moralitas hanya dipengaruhi faktor bawaan.', 'Legalitas otomatis mengikuti kebiasaan.', 'Tindakan tersebut tidak dapat dinilai secara moral.'], 'B', 'Kebiasaan yang salah tidak menjadi benar hanya karena dilakukan banyak orang.'],
      ['Seorang polisi menerima laporan masyarakat, tetapi belum ditemukan bukti bahwa orang yang dilaporkan melakukan tindak pidana. Sikap yang tepat adalah ....', ['Langsung menganggap orang tersebut bersalah.', 'Langsung menjatuhkan hukuman.', 'Menindaklanjuti laporan sesuai prosedur dan tidak menganggap dugaan sebagai bukti kesalahan.', 'Mengabaikan laporan karena belum ada bukti.', 'Mengumumkan identitas orang tersebut sebagai pelaku.'], 'C', 'Dugaan harus diperiksa secara objektif, dan asas praduga tak bersalah harus dihormati.'],
      ['Sebuah organisasi profesi memiliki banyak anggota, tetapi tidak mempunyai tujuan, pembagian tugas, maupun kerja sama. Unsur organisasi yang belum berjalan dengan baik adalah ....', ['Orang saja.', 'Kerja sama dan tujuan.', 'Anggota saja.', 'Pengakuan pemerintah saja.', 'Pendidikan khusus.'], 'B', 'Organisasi tidak cukup hanya memiliki orang; kerja sama dan tujuan yang jelas juga dibutuhkan.'],
      ['Seorang jaksa menerima hadiah dari pengusaha yang perkaranya sedang ditangani, beralasan sebagai tanda terima kasih, bukan untuk membeli putusan. Bagaimana tindakan tersebut harus dinilai?', ['Selalu dibenarkan jika disebut hadiah.', 'Tidak memiliki persoalan etik selama nilainya kecil.', 'Harus dinilai berdasarkan hubungan pemberian dengan jabatan dan ketentuan yang berlaku.', 'Selalu diperbolehkan jika diberikan setelah jam kerja.', 'Tidak dapat diperiksa oleh organisasi profesi.'], 'C', 'Sebutan hadiah tidak otomatis menghilangkan persoalan etik atau hukum.'],
      ['Seorang jaksa ditekan atasan agar segera menyelesaikan perkara tanpa pemeriksaan memadai, lalu menolak menggunakan bukti yang tidak dapat dipertanggungjawabkan. Prinsip yang paling tepat adalah ....', ['Integritas dan profesionalitas.', 'Etika organisasi mahasiswa.', 'Kebijaksanaan gaya hidup.', 'Etika kemasyarakatan polisi.', 'Aliran adat.'], 'A', 'Ia mempertahankan prinsip (integritas) dan bekerja berdasarkan bukti yang sah dan memadai (profesionalitas).'],
      ['Seorang jaksa hidup berkecukupan dengan rumah dan kendaraan bagus. Apakah kondisi tersebut otomatis pelanggaran etika?', ['Ya, karena jaksa dilarang memiliki kekayaan.', 'Ya, karena seluruh jaksa wajib hidup sederhana secara mutlak.', 'Tidak otomatis; bergantung pada ketentuan etik, sumber kekayaan, penyalahgunaan jabatan, dan perilaku yang dilakukan.', 'Ya, karena jaksa tidak boleh memiliki kendaraan.', 'Tidak, karena jaksa bebas melakukan apa pun.'], 'C', 'Modul membedakan memiliki harta dengan memamerkan kemewahan berlebihan atau memperoleh kekayaan lewat penyalahgunaan jabatan.'],
      ['Seorang jaksa mengunggah komentar tentang perkara yang sedang ditanganinya hingga mengungkap informasi yang seharusnya dilindungi. Prinsip yang paling berkaitan adalah ....', ['Aliran adat.', 'Kebijaksanaan.', 'Organisasi.', 'Faktor bawaan.', 'Legalitas saja.'], 'B', 'Kebijaksanaan mengharuskan jaksa mempertimbangkan akibat tindakan, termasuk komunikasi dan penggunaan media sosial.']
    ])],
    ['penguatan', 'Penguatan konsep dan perbedaan istilah', m([
      ['Manakah urutan tahapan dan kewenangan yang paling tepat dalam proses pidana berdasarkan penjelasan modul?', ['Penyelidikan → penyidikan → penuntutan → pemeriksaan, pengadilan, dan putusan.', 'Penuntutan → penyidikan → penyelidikan → putusan.', 'Putusan → penuntutan → penyidikan → penyelidikan.', 'Penyidikan → putusan → penyelidikan → penuntutan.', 'Penyelidikan → putusan → penuntutan → penyidikan.'], 'A', 'Penyelidikan mencari peristiwa, penyidikan mengumpulkan bukti, jaksa menuntut, hakim memeriksa dan memutus.'],
      ['Pasangan institusi atau organisasi dengan kedudukannya yang tepat adalah ....', ['POLRI — organisasi profesi hakim.', 'IKAHI — institusi negara yang menjalankan kepolisian.', 'Kejaksaan — institusi negara yang menjalankan fungsi kejaksaan.', 'INI — institusi negara yang menjalankan fungsi penuntutan.', 'PERSAJA — organisasi profesi notaris.'], 'C', 'IKAHI, INI, dan PERSAJA berkaitan dengan organisasi profesi; kejaksaan adalah institusi.'],
      ['Pernyataan yang paling tepat mengenai hubungan hati nurani dan kode etik adalah ....', ['Hati nurani dapat digunakan untuk membenarkan pelanggaran kode etik.', 'Kode etik menggantikan seluruh kesadaran moral seseorang.', 'Hati nurani membantu menyadari tanggung jawab moral, sedangkan kode etik menetapkan standar perilaku profesional.', 'Hati nurani hanya berlaku untuk masyarakat umum.', 'Kode etik hanya berlaku jika seseorang merasa bersalah.'], 'C', 'Keduanya saling melengkapi. Kesadaran pribadi tidak boleh dijadikan alasan mengabaikan hukum atau kode etik.'],
      ['Contoh yang paling tepat menunjukkan perbedaan hukum moralitas dan hukum positif adalah ....', ['Teguran karena berbohong adalah konsekuensi moral, sedangkan sanksi pidana atas pencurian yang memenuhi unsur adalah konsekuensi hukum positif.', 'Keduanya selalu memberikan sanksi penjara.', 'Keduanya hanya berlaku bagi pejabat.', 'Hukum moralitas selalu tertulis dalam undang-undang.', 'Hukum positif hanya bergantung pada perasaan masyarakat.'], 'A', 'Hukum moralitas terkait penilaian dan tanggung jawab moral; hukum positif terkait aturan hukum yang berlaku.'],
      ['Seorang profesional hukum bertindak jujur, memahami kompetensinya, memeriksa perkara dengan teliti, dan mempertimbangkan dampak tindakannya terhadap masyarakat. Gambaran tersebut menunjukkan ....', ['Hanya kemampuan akademik.', 'Penerapan etika profesi hukum secara menyeluruh.', 'Penggunaan kekuasaan tanpa batas.', 'Pengutamaan keuntungan pribadi.', 'Pengabaian hukum positif.'], 'B', 'Profesional hukum yang baik menggabungkan pengetahuan, integritas, profesionalitas, kebijaksanaan, dan tanggung jawab moral.']
    ])]
  ];
  var all = [], banks = [];
  bab.forEach(function (b) { all = all.concat(b[2]); banks.push({ id: 'epm-' + b[0], title: b[1], course: C, questions: b[2] }); });
  banks.unshift({ id: 'epm-semua', title: 'Modul 1–7: Seluruh materi (145 soal)', course: C, questions: all });
  window.MO_EXAM_BANKS = (window.MO_EXAM_BANKS || []).concat(banks);
})();
;
/* Bank soal: Hukum Acara Perdata. Bentuk tiap soal: [pertanyaan, [pilihan A–E], huruf jawaban, pembahasan] */
(function () {
  var C = 'Hukum Acara Perdata';
  var m = function (a) { return a.map(function (x) { return { q: x[0], o: x[1], a: x[2], e: x[3] }; }); };
  var bab = [
    ['bab1', 'Bab I: Pengantar dan asas-asas', m([
      ['Ahmad meminjamkan uang Rp10.000.000 kepada Budi. Saat jatuh tempo Budi tidak membayar, lalu Ahmad mengajukan gugatan ke pengadilan. Aturan yang mengatur tata cara Ahmad menggugat, menghadirkan bukti, hingga memperoleh putusan hakim disebut ....', ['Hukum Pidana Materiil', 'Hukum Perdata Materiil', 'Hukum Acara Perdata', 'Hukum Tata Negara', 'Hukum Administrasi Negara'], 'C', 'Hukum Acara Perdata mengatur tata cara mempertahankan dan melindungi hak keperdataan melalui pengadilan. Kewajiban Budi membayar utang adalah ranah hukum perdata materiil; prosedur menggugatnya adalah ranah hukum acara perdata.'],
      ['Manakah pernyataan yang paling tepat mengenai perbedaan Hukum Perdata Materiil dan Hukum Acara Perdata?', ['Hukum materiil mengatur hakim, sedangkan hukum acara mengatur polisi.', 'Hukum materiil menentukan hak dan kewajiban, sedangkan hukum acara mengatur cara menegakkan hak tersebut.', 'Hukum materiil hanya berlaku dalam perkara pidana, sedangkan hukum acara hanya dalam perkara perdata.', 'Hukum materiil mengatur proses persidangan, sedangkan hukum acara mengatur perjanjian.', 'Keduanya memiliki pengertian dan fungsi yang sama.'], 'B', 'Materiil = apa hak dan kewajiban seseorang. Acara = bagaimana hak tersebut diperjuangkan.'],
      ['Berikut ini merupakan tujuan Hukum Acara Perdata, kecuali ....', ['Menegakkan hukum materiil.', 'Menyelesaikan sengketa secara tertib.', 'Melindungi hak para pihak.', 'Memberikan kepastian hukum.', 'Memberikan kewenangan kepada pihak yang kuat untuk mengambil hak pihak lain secara langsung.'], 'E', 'Hukum acara justru mencegah penyelesaian sengketa secara sewenang-wenang. Lima tujuannya: menegakkan hukum materiil, menyelesaikan sengketa secara tertib, melindungi hak para pihak, memberi kepastian hukum, dan mewujudkan keadilan.'],
      ['Ahmad mengajukan bukti perjanjian pinjaman, Budi mengajukan bukti bahwa utang telah dibayar. Hakim memeriksa dalil dan bukti kedua belah pihak. Tindakan hakim ini mencerminkan asas ....', ['Keterbukaan', 'Kebenaran formal', 'Persamaan di hadapan hukum', 'Hakim bersifat pasif', 'Sederhana, cepat, dan biaya ringan'], 'B', 'Asas kebenaran formal: hakim memeriksa perkara berdasarkan dalil para pihak dan bukti yang diajukan menurut hukum acara. Bukan berarti hakim menerima semua perkataan para pihak begitu saja.'],
      ['Ahmad menggugat Budi agar membayar utang Rp10.000.000, tetapi hakim memutus bahwa Budi harus menyerahkan sebuah kendaraan yang tidak pernah diminta Ahmad. Konsep yang berkaitan dengan persoalan tersebut adalah ....', ['Asas keterbukaan', 'Asas kebenaran formal', 'Asas hakim bersifat pasif', 'Asas persamaan di hadapan hukum', 'Asas sederhana'], 'C', 'Para pihak menentukan ruang lingkup sengketa dan tuntutan; hakim pada umumnya tidak boleh mengganti tuntutan penggugat dengan tuntutan lain. Pasif bukan berarti diam: hakim tetap memimpin sidang, mengupayakan perdamaian, memeriksa, dan memutus.'],
      ['Ahmad masyarakat biasa, Budi pejabat terkenal. Di persidangan keduanya diberi kesempatan yang sama untuk berpendapat dan mengajukan bukti. Hal ini mencerminkan asas ....', ['Kebenaran formal', 'Persamaan di hadapan hukum', 'Hakim bersifat pasif', 'Keterbukaan', 'Biaya ringan'], 'B', 'Setiap pihak diperlakukan setara tanpa membedakan kedudukan sosial, jabatan, kekayaan, atau status.'],
      ['Pada dasarnya, persidangan perkara perdata dilaksanakan ....', ['Secara tertutup tanpa pengecualian.', 'Hanya dihadiri hakim dan penggugat.', 'Terbuka untuk umum, kecuali perkara atau keadaan tertentu yang menurut hukum diperiksa tertutup.', 'Hanya boleh dihadiri keluarga para pihak.', 'Tanpa pengawasan masyarakat.'], 'C', 'Asas keterbukaan menciptakan transparansi dan memungkinkan pengawasan masyarakat, tetapi bukan berarti seluruh informasi perkara boleh disebarluaskan tanpa batas.'],
      ['Pengadilan berupaya menyelesaikan perkara tanpa prosedur berbelit-belit, menghindari penundaan yang tidak perlu, dan menjaga biaya tetap terjangkau. Ini penerapan ....', ['Asas hakim pasif', 'Asas kebenaran formal', 'Asas keterbukaan', 'Asas sederhana, cepat, dan biaya ringan', 'Asas persamaan hukum'], 'D', 'Sederhana = tidak berbelit; cepat = selesai dalam waktu wajar; biaya ringan = terjangkau. Cepat bukan berarti boleh memutus tergesa-gesa tanpa memberi kesempatan yang layak kepada para pihak.']
    ])],
    ['bab2', 'Bab II: Sejarah dan sumber hukum', m([
      ['Perkembangan Hukum Acara Perdata di Indonesia tidak dapat dilepaskan dari masa penjajahan Belanda karena ....', ['Belanda menciptakan seluruh hukum perdata modern Indonesia setelah kemerdekaan.', 'Pada masa kolonial terdapat peraturan dan sistem peradilan berbeda berdasarkan kelompok penduduk dan wilayah tertentu.', 'Indonesia tidak memiliki pengadilan sebelum kemerdekaan.', 'HIR dan RBg dibuat setelah Indonesia merdeka.', 'Hukum acara perdata hanya berlaku untuk masyarakat Belanda.'], 'B', 'Pemerintah Hindia Belanda menerapkan peraturan dan sistem peradilan berbeda untuk kelompok penduduk dan wilayah tertentu, sehingga sejarah hukum acara perdata dipengaruhi lebih dari satu peraturan.'],
      ['HIR merupakan singkatan dari ....', ['Herziene Indonesisch Reglement', 'Rechtsreglement voor de Buitengewesten', 'Herziene Indonesian Recht', 'Het Indonesisch Reglement', 'Hukum Indonesia Reglement'], 'A', 'HIR = Herziene Indonesisch Reglement, secara historis terutama berlaku untuk Jawa dan Madura.'],
      ['RBg merupakan singkatan dari ....', ['Rechtsboek voor Indonesische Gebieden', 'Rechtsreglement voor de Buitengewesten', 'Reglement voor de Buitenlandse Gebieden', 'Rechtsregeling binnen Indonesië', 'Reglement Burgerlijke Geschillen'], 'B', 'RBg = Rechtsreglement voor de Buitengewesten, secara historis berlaku untuk wilayah di luar Jawa dan Madura. Hafalan: HIR = Jawa dan Madura; RBg = luar Jawa dan Madura.'],
      ['Mengapa HIR dan RBg masih ditemukan dalam pembahasan Hukum Acara Perdata setelah Indonesia merdeka?', ['Karena Indonesia tidak memiliki peraturan hukum baru.', 'Karena seluruh peraturan kolonial tidak boleh diubah.', 'Karena ketentuan lama tetap menjadi bagian praktik peradilan sepanjang masih berlaku dan tidak bertentangan dengan peraturan yang lebih baru.', 'Karena Indonesia masih berada di bawah pemerintahan Belanda.', 'Karena HIR dan RBg merupakan hukum internasional.'], 'C', 'Kemerdekaan tidak otomatis mengganti seluruh sistem hukum yang ada. Perubahan berlangsung bertahap melalui peraturan baru, penyesuaian kelembagaan, dan perkembangan praktik peradilan.'],
      ['Berikut ini yang termasuk sumber Hukum Acara Perdata berdasarkan modul adalah ....', ['HIR, RBg, undang-undang, serta peraturan terkait penyelenggaraan peradilan.', 'Hanya KUHP.', 'Hanya peraturan pemerintah daerah.', 'Hanya hukum adat.', 'Hanya keputusan hakim.'], 'A', 'Sumber penting: HIR, RBg, undang-undang, serta peraturan lain terkait kekuasaan kehakiman, peradilan, administrasi perkara, dan prosedur khusus.'],
      ['Pasangan yang tepat mengenai Pasal 163 HIR dan Pasal 164 HIR adalah ....', ['Pasal 163 HIR mengatur alat bukti, Pasal 164 HIR mengatur pengadilan.', 'Pasal 163 HIR mengatur beban pembuktian, Pasal 164 HIR mengatur alat bukti.', 'Pasal 163 HIR mengatur gugatan, Pasal 164 HIR mengatur hakim.', 'Pasal 163 HIR mengatur pemanggilan, Pasal 164 HIR mengatur putusan.', 'Keduanya mengatur intervensi.'], 'B', 'Pasal 163 HIR: prinsip beban pembuktian. Pasal 164 HIR: alat bukti dalam perkara perdata. Keduanya berkaitan erat dengan Bab IX tentang pembuktian.']
    ])],
    ['bab3', 'Bab III: Kekuasaan kehakiman dan pengadilan', m([
      ['Pengadilan dalam pengertian hukum adalah ....', ['Bangunan tempat masyarakat berkumpul.', 'Lembaga atau satuan penyelenggara peradilan yang memeriksa dan memutus perkara sesuai kewenangannya.', 'Organisasi yang bertugas membuat undang-undang.', 'Lembaga yang hanya menangani perkara pidana.', 'Organisasi yang mewakili kepentingan penggugat.'], 'B', 'Pengadilan bukan sekadar bangunan fisik, melainkan bagian dari sistem peradilan yang menjalankan fungsi mengadili: memeriksa tuntutan, menilai bukti, menerapkan hukum, dan menghasilkan putusan.'],
      ['Manakah pernyataan yang benar?', ['Pengadilan adalah pejabat, sedangkan hakim adalah lembaga.', 'Pengadilan dan hakim memiliki pengertian yang sama.', 'Pengadilan merupakan lembaga penyelenggara peradilan, sedangkan hakim merupakan pejabat yang menjalankan fungsi mengadili.', 'Hakim merupakan lembaga yang menaungi pengadilan.', 'Pengadilan hanya bertugas mengawasi hakim.'], 'C', 'Pengadilan = lembaga. Hakim = pejabat yang mengadili. Satu pengadilan dapat memiliki banyak hakim.'],
      ['Kekuasaan kehakiman di Indonesia diselenggarakan melalui berapa lingkungan peradilan di bawah Mahkamah Agung?', ['Dua', 'Tiga', 'Empat', 'Lima', 'Enam'], 'C', 'Empat lingkungan peradilan: Peradilan Umum, Peradilan Agama, Peradilan Militer, dan Peradilan Tata Usaha Negara.'],
      ['Ahmad menggugat Budi karena tidak memenuhi kewajiban pembayaran utang berdasarkan perjanjian biasa. Perkara tersebut pada umumnya menjadi kewenangan ....', ['Peradilan Militer', 'Peradilan Agama', 'Peradilan Tata Usaha Negara', 'Peradilan Umum', 'Mahkamah Konstitusi'], 'D', 'Peradilan Umum menangani antara lain perkara pidana dan perdata umum, misalnya sengketa pembayaran utang berdasarkan perjanjian.'],
      ['Perkara perceraian bagi orang Islam yang termasuk kewenangan absolut Peradilan Agama diperiksa oleh ....', ['Peradilan Umum', 'Peradilan Militer', 'Peradilan Agama', 'Peradilan Tata Usaha Negara', 'Mahkamah Konstitusi'], 'C', 'Peradilan Agama menangani perkara tertentu bagi orang yang tunduk pada kewenangannya, termasuk perkawinan dan kewarisan Islam.'],
      ['Pasangan perkara dan lingkungan peradilan yang tepat adalah ....', ['Sengketa pembayaran utang — Peradilan Militer.', 'Perceraian Muslim — Peradilan TUN.', 'Sengketa keputusan pemerintahan — Peradilan Tata Usaha Negara.', 'Perkara kewarisan Islam — Peradilan Militer.', 'Sengketa kontrak biasa — Peradilan Agama.'], 'C', 'Peradilan TUN menangani sengketa tata usaha negara, termasuk sengketa terkait keputusan atau tindakan pemerintahan. Peradilan Militer menangani perkara dalam kewenangan peradilan militer.']
    ])],
    ['bab4', 'Bab IV: Hakim dan tugasnya', m([
      ['Hakim adalah ....', ['Orang yang mengajukan gugatan.', 'Pejabat yang menjalankan kekuasaan kehakiman untuk memeriksa, mengadili, dan memutus perkara sesuai kewenangannya.', 'Petugas yang bertugas memanggil para pihak.', 'Orang yang menyusun gugatan penggugat.', 'Petugas administrasi pengadilan.'], 'B', 'Dalam perkara perdata, hakim memeriksa dalil kedua pihak, menilai bukti, menerapkan hukum, dan menjatuhkan putusan.'],
      ['Berikut ini yang bukan merupakan tugas hakim berdasarkan modul adalah ....', ['Memeriksa perkara.', 'Mengupayakan perdamaian.', 'Memimpin persidangan.', 'Memeriksa bukti.', 'Membuat perjanjian utang antara penggugat dan tergugat.'], 'E', 'Enam tugas hakim: memeriksa perkara, mengupayakan perdamaian, memimpin persidangan, memeriksa bukti, menerapkan hukum, dan menjatuhkan putusan.'],
      ['Suatu perkara diperiksa dan diadili oleh satu orang hakim karena ketentuan hukum memperbolehkannya. Bentuk pemeriksaan tersebut disebut ....', ['Majelis hakim', 'Hakim tunggal', 'Hakim pengawas', 'Hakim mediator', 'Hakim penuntut'], 'B', 'Hakim tunggal adalah pemeriksaan perkara oleh satu hakim, apabila hukum memperbolehkan.'],
      ['Perkara diperiksa dan diadili oleh beberapa hakim yang bekerja bersama dalam satu susunan majelis. Hal tersebut disebut ....', ['Hakim tunggal', 'Hakim mediator', 'Majelis hakim', 'Hakim pengawas', 'Hakim administrasi'], 'C', 'Majelis hakim adalah beberapa hakim yang mengadili bersama. Bentuk dan susunan hakim mengikuti ketentuan jenis perkara.']
    ])],
    ['bab5', 'Bab V: Gugatan', m([
      ['Gugatan dalam Hukum Acara Perdata adalah ....', ['Laporan dugaan tindak pidana kepada kepolisian.', 'Tuntutan hak yang diajukan ke pengadilan oleh pihak yang merasa hak atau kepentingan hukumnya dilanggar atau disengketakan.', 'Permohonan seseorang untuk menjadi hakim.', 'Laporan masyarakat kepada pemerintah.', 'Kesepakatan antara dua pihak untuk menyelesaikan utang.'], 'B', 'Gugatan diajukan ke pengadilan untuk memperjuangkan hak keperdataan, berbeda dari laporan polisi yang menyampaikan dugaan tindak pidana kepada kepolisian.'],
      ['Ahmad menggugat Budi karena Budi tidak membayar utang berdasarkan perjanjian. Kedudukan Ahmad dan Budi adalah ....', ['Ahmad tergugat, Budi penggugat.', 'Ahmad saksi, Budi hakim.', 'Ahmad penggugat, Budi tergugat.', 'Ahmad hakim, Budi penggugat.', 'Ahmad dan Budi sama-sama tergugat.'], 'C', 'Penggugat = pihak yang mengajukan gugatan. Tergugat = pihak yang digugat. Status tergugat tidak berarti sudah terbukti bersalah.'],
      ['Penggugat harus mencantumkan identitas dirinya dan pihak yang digugat agar tidak terjadi kekeliruan mengenai pihak dalam perkara. Bagian tersebut disebut ....', ['Posita', 'Petitum', 'Identitas para pihak', 'Eksepsi', 'Rekonvensi'], 'C', 'Identitas para pihak menjelaskan siapa yang menuntut dan siapa yang dituntut, dan harus memadai agar para pihak dapat dikenali secara tepat.'],
      ['Uraian mengenai fakta dan dasar hukum yang menjadi alasan Ahmad menggugat Budi (ada perjanjian pinjaman, Budi wajib membayar, tetapi belum melunasi) disebut ....', ['Petitum', 'Posita', 'Eksepsi', 'Relaas', 'Renvoi'], 'B', 'Posita (fundamentum petendi) adalah dasar atau alasan gugatan: fakta yang mendasari tuntutan dan dasar hukum yang relevan. Posita menjawab: mengapa penggugat menuntut?'],
      ['Ahmad meminta hakim menjatuhkan putusan agar Budi dihukum membayar utang Rp10.000.000. Bagian gugatan yang berisi permintaan tersebut disebut ....', ['Identitas', 'Posita', 'Petitum', 'Eksepsi', 'Relaas'], 'C', 'Petitum berisi hal-hal yang diminta penggugat agar diputus hakim. Posita = mengapa menggugat; petitum = apa yang diminta.'],
      ['Manakah susunan unsur pokok gugatan yang tepat berdasarkan modul?', ['Identitas para pihak, posita, dan petitum.', 'Identitas, eksepsi, dan putusan.', 'Posita, replik, dan duplik.', 'Petitum, pembuktian, dan putusan.', 'Identitas, relaas, dan intervensi.'], 'A', 'Tiga unsur pokok gugatan: identitas para pihak, posita (fundamentum petendi), dan petitum.'],
      ['Seseorang hendak menggugat sendiri. Salah satu hal yang harus diperhatikan adalah apakah ia mampu melakukan tindakan hukum sendiri menurut ketentuan yang berlaku. Hal ini disebut ....', ['Kepentingan hukum', 'Kecakapan hukum', 'Kebenaran formal', 'Kewenangan relatif', 'Intervensi'], 'B', 'Kecakapan hukum adalah kemampuan melakukan tindakan hukum sendiri. Dalam keadaan tertentu seseorang bertindak melalui wali atau wakil yang sah, dan kecakapan tidak boleh dinilai dari satu faktor (misalnya usia) saja.'],
      ['Citra menggugat seseorang hanya karena tidak menyukai perilakunya, padahal Citra tidak memiliki hubungan hukum atau kepentingan yang relevan terhadap objek sengketa. Persoalan utama yang mungkin timbul adalah ....', ['Tidak adanya hakim tunggal', 'Tidak adanya kepentingan hukum yang relevan', 'Tidak adanya relaas panggilan', 'Tidak adanya putusan sela', 'Tidak adanya alat bukti sumpah'], 'B', 'Seseorang tidak dapat menggugat hanya karena tidak menyukai tindakan orang lain. Gugatan harus memiliki kepentingan hukum yang relevan.'],
      ['Apakah seseorang yang memiliki legal standing pasti memenangkan perkara?', ['Ya, karena legal standing berarti seluruh tuntutannya benar.', 'Ya, karena hakim wajib mengabulkan gugatannya.', 'Tidak, karena legal standing merupakan kedudukan hukum untuk mengajukan tuntutan, bukan jaminan kemenangan.', 'Tidak, karena legal standing hanya berlaku bagi hakim.', 'Ya, selama seseorang memiliki bukti tertulis.'], 'C', 'Legal standing = berhak mengajukan tuntutan. Kemenangan ditentukan lewat pemeriksaan perkara dan pembuktian. Seseorang bisa berhak menggugat, tetapi tuntutannya belum tentu terbukti.'],
      ['Beberapa orang memiliki kepentingan hukum atas satu objek sengketa dan mengajukan gugatan bersama-sama berdasarkan hubungan kepentingan yang memungkinkan. Bentuk gugatan tersebut termasuk ....', ['Satu penggugat dan satu tergugat', 'Beberapa penggugat', 'Beberapa tergugat', 'Intervensi', 'Vrijwaring'], 'B', 'Jenis gugatan menurut jumlah pihak: satu penggugat dan satu tergugat, beberapa penggugat, dan beberapa tergugat. Susunan para pihak tetap harus sesuai hubungan hukum dan tuntutan yang diajukan.']
    ])],
    ['bab6', 'Bab VI: Tahapan sebelum persidangan (PMH dan PHS)', m([
      ['Setelah gugatan didaftarkan, ketua pengadilan menetapkan hakim yang akan memeriksa dan mengadili perkara. Penetapan tersebut disebut ....', ['PHS', 'PMH', 'Relaas', 'Petitum', 'Eksepsi'], 'B', 'PMH = Penetapan Majelis Hakim: menetapkan ketua dan anggota majelis, serta memerintahkan penetapan hari sidang.'],
      ['Setelah majelis hakim ditetapkan, ketua majelis menentukan tanggal sidang dan memberi instruksi persiapan pemanggilan para pihak. Penetapan tersebut disebut ....', ['PMH', 'PHS', 'RBg', 'HIR', 'Renvoi'], 'B', 'PHS = Penetapan Hari Sidang: menentukan kapan perkara disidangkan dan persiapan pemanggilan para pihak.'],
      ['Manakah pasangan yang paling tepat?', ['PMH menentukan hari sidang, PHS menentukan alat bukti.', 'PMH menunjuk majelis hakim, PHS menentukan hari sidang.', 'PMH memanggil tergugat, PHS mengajukan gugatan.', 'PMH mengatur intervensi, PHS mengatur eksepsi.', 'PMH mengatur putusan akhir, PHS mengatur putusan sela.'], 'B', 'PMH menjawab: siapa hakim yang menangani perkara? PHS menjawab: kapan perkara disidangkan?'],
      ['Berikut ini isi pokok PHS menurut modul, kecuali ....', ['Penetapan hari dan tanggal sidang.', 'Perintah juru sita memanggil para pihak.', 'Perintah menyerahkan salinan gugatan.', 'Peringatan mengenai jarak waktu pemanggilan dan hari sidang.', 'Penetapan bahwa penggugat pasti memenangkan perkara.'], 'E', 'PHS berisi instruksi administratif dan persiapan persidangan, bukan penentuan siapa yang menang. Modul mencatat jarak pemanggilan dengan hari sidang tidak boleh kurang dari tiga hari kerja; penerapan nyata tetap perlu diperiksa pada ketentuan yang berlaku.']
    ])],
    ['bab7', 'Bab VII: Pemanggilan para pihak', m([
      ['Pemanggilan dalam Hukum Acara Perdata merupakan ....', ['Tindakan hakim untuk menjatuhkan putusan.', 'Tindakan prosedural memberitahukan kepada pihak berkepentingan bahwa ia harus hadir atau melakukan sesuatu dalam proses peradilan.', 'Tindakan penggugat untuk membatalkan gugatan.', 'Tindakan tergugat untuk mengajukan bukti.', 'Tindakan pihak ketiga untuk masuk ke perkara.'], 'B', 'Tujuan pemanggilan adalah agar para pihak mengetahui dan dapat mengikuti proses persidangan.'],
      ['Dokumen resmi yang mencatat pelaksanaan pemanggilan oleh petugas berwenang, yaitu juru sita, disebut ....', ['Petitum', 'Posita', 'Relaas panggilan', 'PHS', 'PMH'], 'C', 'Relaas dapat mencatat: juru sita bertemu pihak yang dipanggil, tidak bertemu, atau bertemu tetapi pihak itu tidak mau menandatangani. Relaas penting untuk menilai apakah pemanggilan sesuai prosedur.'],
      ['Juru sita telah bertemu Budi dan menyampaikan surat panggilan, tetapi Budi menolak menandatangani relaas. Tindakan yang tepat berdasarkan modul adalah ....', ['Pemanggilan otomatis batal.', 'Perkara otomatis dihentikan.', 'Keadaan penolakan dicatat dalam relaas sesuai fakta pelaksanaan pemanggilan.', 'Budi otomatis dinyatakan kalah.', 'Hakim langsung menjatuhkan putusan verstek.'], 'C', 'Penolakan menandatangani tidak otomatis berarti pemanggilan tidak pernah terjadi. Juru sita mencatat keadaan sebenarnya secara akurat.'],
      ['Seorang tetangga memberi tahu Budi bahwa minggu depan ada sidang, tetapi tidak ada pemanggilan melalui prosedur oleh petugas berwenang. Persoalan yang paling berkaitan adalah pelanggaran asas ....', ['Patut', 'Resmi', 'Kebenaran formal', 'Hakim pasif', 'Keterbukaan'], 'B', 'Asas resmi berhubungan dengan kewenangan petugas dan prosedur pemanggilan. Pemberitahuan dari tetangga tidak dapat menggantikan pemanggilan resmi.'],
      ['Pemanggilan telah dilakukan petugas berwenang, tetapi jarak waktu antara pemanggilan dan hari sidang tidak memberi kesempatan layak untuk mempersiapkan diri. Persoalan tersebut berkaitan dengan asas ....', ['Resmi', 'Patut', 'Hakim pasif', 'Kebenaran formal', 'Legal standing'], 'B', 'Asas resmi = apakah pemanggilan dilakukan secara sah (kewenangan petugas dan prosedur). Asas patut = apakah pihak mendapat kesempatan layak (kepatutan cara dan waktu).'],
      ['Budi sebagai tergugat tidak menghadiri persidangan meskipun perkara telah dijadwalkan. Manakah pernyataan yang benar?', ['Hakim wajib langsung memenangkan penggugat.', 'Ketidakhadiran tergugat selalu menyebabkan putusan verstek.', 'Hakim harus memperhatikan terpenuhinya persyaratan hukum acara sebelum mempertimbangkan putusan verstek.', 'Perkara otomatis dibatalkan.', 'Penggugat otomatis menjadi tergugat.'], 'C', 'Verstek adalah putusan tanpa kehadiran tergugat dalam keadaan yang memenuhi persyaratan hukum acara, antara lain pemanggilan sah dan patut. Tidak hadir adalah keadaan faktual; verstek adalah kemungkinan putusan. Dalil penggugat juga tidak otomatis dianggap benar tanpa pemeriksaan.']
    ])],
    ['bab8', 'Bab VIII: Jalannya persidangan dan jawaban tergugat', m([
      ['Ahmad menggugat Budi karena tidak membayar utang. Keduanya hadir, lalu majelis hakim berupaya agar mereka menyelesaikan sengketa melalui perdamaian. Tindakan tersebut merupakan ....', ['Pemeriksaan alat bukti', 'Upaya perdamaian', 'Putusan verstek', 'Intervensi', 'Eksepsi'], 'B', 'Ketika kedua pihak hadir, hakim mengupayakan perdamaian lebih dulu. Jika berhasil dan memenuhi persyaratan, penyelesaiannya dituangkan dalam bentuk yang berakibat hukum; jika gagal, perkara dilanjutkan.'],
      ['Jika upaya perdamaian tidak berhasil, tahap selanjutnya menurut urutan dalam modul adalah ....', ['Hakim langsung menjatuhkan putusan akhir.', 'Penggugat diberi kesempatan membacakan gugatan.', 'Tergugat langsung dinyatakan kalah.', 'Perkara otomatis dibatalkan.', 'Pihak ketiga langsung masuk ke persidangan.'], 'B', 'Alur: kedua pihak hadir, upaya perdamaian, perdamaian gagal, penggugat membacakan gugatan, pemeriksaan berlanjut. Dalam praktik, ketentuan mediasi yang berlaku juga harus diperhatikan.'],
      ['Ahmad menemukan kesalahan penulisan alamat Budi dalam surat gugatan, lalu memperbaikinya agar identitas tergugat jelas. Tindakan Ahmad disebut ....', ['Perubahan pokok perkara', 'Perbaikan gugatan', 'Eksepsi', 'Rekonvensi', 'Intervensi'], 'B', 'Perbaikan gugatan memperjelas atau membetulkan bagian yang keliru. Berbeda dengan perubahan gugatan yang dapat mengubah bagian tertentu, termasuk dasar sengketa atau tuntutan.'],
      ['Menurut ringkasan catatan modul, penggugat masih diberi kesempatan meralat atau mengubah gugatan ketika ....', ['Hakim telah menjatuhkan putusan akhir.', 'Tergugat belum memberikan jawaban.', 'Perkara telah selesai.', 'Pengadilan telah menolak gugatan.', 'Pihak ketiga telah masuk ke perkara.'], 'B', 'Waktu perubahan gugatan penting karena memengaruhi hak tergugat untuk membela diri. Perubahan setelah tergugat menjawab berkaitan dengan persetujuan tergugat; penerapan sebenarnya tetap mengikuti ketentuan hukum acara.'],
      ['Angka Rp5.000.000 dalam gugatan seharusnya Rp6.000.000. Kesalahan dikoreksi dengan mencoret angka lama tanpa menghilangkan keterbacaannya, lalu menuliskan angka yang benar. Teknik koreksi tersebut disebut ....', ['Eksepsi', 'Renvoi', 'Rekonvensi', 'Voeging', 'Verstek'], 'B', 'Renvoi adalah teknik koreksi tulisan yang tetap mempertahankan keterbacaan tulisan semula dan mencantumkan koreksi secara transparan, agar perubahan tidak dilakukan diam-diam.'],
      ['Budi mengajukan keberatan karena menurutnya pengadilan yang memeriksa perkara tidak memiliki kewenangan relatif untuk menangani sengketa tersebut. Keberatan tersebut termasuk ....', ['Petitum', 'Posita', 'Eksepsi', 'Pengakuan', 'Pembuktian'], 'C', 'Eksepsi adalah keberatan tergugat atas persoalan tertentu, terutama aspek prosedural atau hukum acara, misalnya kewenangan pengadilan. Eksepsi tidak langsung membahas apakah utang sudah dibayar.'],
      ['Ahmad menyatakan Budi belum membayar utang Rp10.000.000. Budi menyangkal dan mengatakan utang telah dilunasi. Jawaban Budi termasuk ....', ['Eksepsi', 'Bantahan terhadap pokok perkara', 'Intervensi', 'Relaas', 'PMH'], 'B', 'Bantahan adalah jawaban tergugat yang menyangkal dalil penggugat. Budi tidak mempersoalkan kewenangan pengadilan, tetapi membantah substansi tuntutan.'],
      ['Budi berkata: “Saya memang pernah menerima pinjaman dari Ahmad, tetapi uang tersebut sudah saya lunasi.” Pernyataan tersebut menunjukkan ....', ['Pengakuan atas fakta pinjaman sekaligus adanya bantahan mengenai pelunasan.', 'Penolakan seluruh fakta gugatan.', 'Eksepsi kewenangan absolut.', 'Putusan verstek.', 'Intervensi pihak ketiga.'], 'A', 'Fakta penerimaan pinjaman diakui, fakta pelunasan masih harus diperiksa jika diperselisihkan. Pengakuan atas satu fakta tidak otomatis berarti mengakui seluruh tuntutan penggugat.'],
      ['Manakah pasangan yang tepat?', ['Eksepsi = mengakui utang; bantahan = meminta perdamaian; pengakuan = keberatan kewenangan.', 'Eksepsi = keberatan prosedural; bantahan = menyangkal dalil; pengakuan = membenarkan fakta tertentu.', 'Eksepsi = pembuktian; bantahan = putusan hakim; pengakuan = intervensi.', 'Eksepsi = gugatan; bantahan = relaas; pengakuan = PMH.', 'Ketiganya memiliki pengertian sama.'], 'B', 'Eksepsi: keberatan atas persoalan tertentu, terutama prosedural. Bantahan: menyangkal dalil penggugat. Pengakuan: membenarkan fakta tertentu.']
    ])],
    ['bab9', 'Bab IX: Pembuktian', m([
      ['Ahmad menyatakan Budi memiliki utang Rp10.000.000, Budi menyangkal. Untuk mengetahui kebenaran dalil yang diperselisihkan, pengadilan melakukan ....', ['Pemanggilan', 'Pembuktian', 'Intervensi', 'Renvoi', 'PMH'], 'B', 'Pembuktian adalah proses memeriksa dan menilai dalil berdasarkan alat bukti yang diajukan menurut hukum acara. Dalil yang diperselisihkan perlu dibuktikan.'],
      ['Pasal 163 HIR dalam modul berkaitan dengan ....', ['Kewenangan pengadilan', 'Beban pembuktian', 'Penunjukan majelis hakim', 'Pemanggilan para pihak', 'Jenis intervensi'], 'B', 'Pasal 163 HIR membahas prinsip beban pembuktian. Dalam praktik, pembagiannya tidak sesederhana bahwa siapa pun yang membantah selalu harus membuktikan; penentuannya melihat dalil, fakta yang diperselisihkan, dan ketentuan yang berlaku.'],
      ['Berdasarkan Pasal 164 HIR sebagaimana dijelaskan dalam modul, terdapat berapa alat bukti utama?', ['Dua', 'Tiga', 'Empat', 'Lima', 'Enam'], 'D', 'Lima alat bukti: surat, saksi, persangkaan, pengakuan, sumpah. Kunci hafalan: S–S–P–P–S.'],
      ['Ahmad mengajukan perjanjian pinjaman tertulis antara dirinya dan Budi untuk membuktikan adanya hubungan utang piutang. Alat bukti yang digunakan adalah ....', ['Saksi', 'Surat', 'Sumpah', 'Persangkaan', 'Pengakuan'], 'B', 'Bukti surat berbentuk tulisan atau dokumen, misalnya perjanjian tertulis, kuitansi, dokumen kepemilikan. Adanya surat tidak otomatis membuktikan seluruh dalil; keaslian, isi, dan jenisnya tetap diperhatikan.'],
      ['Seseorang hadir ketika Ahmad dan Budi membuat perjanjian pinjaman, lalu memberikan keterangan tentang kejadian itu di pengadilan. Ia memberikan alat bukti berupa ....', ['Surat', 'Persangkaan', 'Saksi', 'Pengakuan', 'Sumpah'], 'C', 'Saksi memberikan keterangan mengenai fakta yang relevan. Keterangannya dinilai menurut hukum acara dan dasar pengetahuannya diperhatikan.'],
      ['Hakim menarik kesimpulan dari beberapa fakta yang saling berkaitan untuk memperoleh kesimpulan mengenai fakta lain yang relevan. Alat bukti yang dimaksud adalah ....', ['Surat', 'Saksi', 'Persangkaan', 'Pengakuan', 'Sumpah'], 'C', 'Persangkaan adalah kesimpulan yang ditarik dari fakta atau keadaan menurut hukum. Persangkaan tidak boleh sekadar dugaan tanpa dasar.'],
      ['Budi mengatakan di persidangan bahwa dirinya memang pernah meminjam uang kepada Ahmad. Pernyataan tersebut merupakan alat bukti ....', ['Surat', 'Saksi', 'Persangkaan', 'Pengakuan', 'Sumpah'], 'D', 'Pengakuan adalah pernyataan mengenai fakta yang relevan. Modul mengaitkannya dengan Pasal 174 HIR dan menjelaskan bahwa dalam keadaan tertentu pengakuan dapat memiliki kekuatan pembuktian sempurna; kekuatannya tetap dilihat dari bentuk, fakta yang diakui, dan konteksnya.'],
      ['Salah satu pihak memberikan sumpah menurut prosedur hukum acara sebagai alat bukti dalam perkara perdata. Alat bukti tersebut adalah ....', ['Surat', 'Saksi', 'Persangkaan', 'Pengakuan', 'Sumpah'], 'E', 'Sumpah adalah alat bukti yang diatur dalam hukum acara. Bukan sekadar pernyataan bahwa seseorang jujur, tetapi mengikuti jenis dan prosedur hukum yang berlaku.'],
      ['Menurut ringkasan modul yang merujuk Pasal 145, 171, dan 172 HIR, kelompok yang disebut dalam daftar orang yang tidak dapat menjadi saksi adalah ....', ['Semua orang dewasa.', 'Keluarga sedarah, suami atau istri meskipun telah bercerai, anak yang belum diketahui sudah berusia 15 tahun, serta orang yang mengalami gangguan jiwa.', 'Semua tetangga para pihak.', 'Semua teman penggugat.', 'Semua orang yang tidak mempunyai dokumen identitas.'], 'B', 'Daftar ini hanya ringkasan, bukan uraian lengkap hukum kesaksian. Hubungan keluarga, usia, kondisi, pengecualian, dan kelayakan saksi diperiksa menurut ketentuan yang berlaku; jangan menyimpulkan setiap anggota keluarga selalu dilarang menjadi saksi.'],
      ['Saksi A melihat sendiri Ahmad menyerahkan uang kepada Budi. Saksi B hanya mendengar cerita penyerahan uang tersebut dari orang lain. Hal yang perlu diperhatikan hakim adalah ....', ['Saksi B pasti lebih kuat karena mengetahui cerita dari orang lain.', 'Semua keterangan saksi memiliki kekuatan yang sama.', 'Dasar pengetahuan dan kualitas keterangan masing-masing saksi.', 'Jumlah teman yang dimiliki saksi.', 'Status sosial saksi.'], 'C', 'Hakim menilai bagaimana saksi memperoleh pengetahuannya. Kualitas keterangan dan kelayakan saksi lebih penting daripada jumlah saksi.'],
      ['Budi mengakui pernah menerima pinjaman dari Ahmad, tetapi menyatakan telah melunasi seluruh utangnya. Apa yang masih harus diperiksa?', ['Apakah Ahmad pernah mengenal Budi.', 'Apakah benar telah terjadi pelunasan utang.', 'Apakah Budi pernah menjadi saksi.', 'Apakah Ahmad memiliki pekerjaan.', 'Apakah Budi pernah menjadi hakim.'], 'B', 'Penerimaan pinjaman sudah diakui, tetapi pelunasan masih menjadi persoalan. Bukti pembayaran menjadi penting. Pengakuan tidak selalu menyelesaikan seluruh persoalan pembuktian.']
    ])],
    ['bab10', 'Bab X: Intervensi', m([
      ['Ahmad menggugat Budi soal kepemilikan tanah. Saat perkara diperiksa, Citra datang dan menyatakan dirinya juga memiliki kepentingan hukum terhadap tanah tersebut. Keterlibatan Citra dikenal dengan istilah ....', ['Eksepsi', 'Rekonvensi', 'Intervensi', 'Verstek', 'Renvoi'], 'C', 'Intervensi (dari intervenire, campur tangan) adalah keterlibatan pihak ketiga dalam perkara yang sedang diperiksa. Pihak ketiga semula bukan penggugat atau tergugat, tetapi memiliki kepentingan hukum yang berkaitan dengan perkara.'],
      ['Manakah pernyataan yang benar mengenai intervensi berdasarkan modul?', ['Setiap orang bebas masuk ke persidangan tanpa persetujuan hakim.', 'Pihak ketiga otomatis menjadi penggugat.', 'Pihak ketiga harus mengajukan permohonan dan hakim menentukan melalui putusan sela apakah dikabulkan atau ditolak.', 'Intervensi hanya dapat dilakukan oleh hakim.', 'Intervensi selalu mengakibatkan perkara dihentikan.'], 'C', 'Pihak ketiga tidak otomatis menjadi pihak hanya karena mengaku punya kepentingan. Ia harus mengajukan permohonan, lalu hakim mempertimbangkannya.'],
      ['Citra memiliki kepentingan hukum atas sengketa tanah Ahmad dan Budi, lalu mengajukan permohonan untuk bergabung mendukung Ahmad sebagai penggugat. Jenis intervensinya adalah ....', ['Tussenkomst', 'Vrijwaring', 'Voeging', 'Eksepsi', 'Verstek'], 'C', 'Voeging = bergabung MENDUKUNG salah satu pihak. Menurut catatan modul, jika Citra mendukung penggugat, penamaan pihak dapat menjadi Penggugat I dan Penggugat II.'],
      ['Citra masuk ke perkara dengan menyatakan tanah itu sebenarnya miliknya sendiri. Ia tidak sekadar membantu Ahmad atau Budi, melainkan memperjuangkan haknya sendiri. Jenis intervensi tersebut disebut ....', ['Voeging', 'Tussenkomst', 'Vrijwaring', 'Eksepsi', 'Pengakuan'], 'B', 'Tussenkomst = masuk memperjuangkan KEPENTINGAN SENDIRI. Menurut modul, pihak ketiga disebut pelawan, sedangkan penggugat dan tergugat menjadi pihak yang berlawanan dengannya.'],
      ['Budi berpendapat bahwa bila ia dinyatakan bertanggung jawab, ada pihak ketiga yang berdasarkan hubungan hukum seharusnya menjamin atau menanggung akibatnya, lalu meminta pihak ketiga itu ditarik ke dalam perkara. Jenis intervensinya adalah ....', ['Voeging', 'Tussenkomst', 'Vrijwaring', 'Verstek', 'Renvoi'], 'C', 'Vrijwaring = pihak ketiga DITARIK ke dalam perkara oleh salah satu pihak melalui mekanisme hukum. Pembedanya dengan voeging dan tussenkomst adalah inisiatif masuknya pihak ketiga.'],
      ['Manakah pasangan yang benar?', ['Voeging = membela kepentingan sendiri; Tussenkomst = mendukung pihak lain; Vrijwaring = mengajukan gugatan.', 'Voeging = mendukung salah satu pihak; Tussenkomst = membela kepentingan sendiri; Vrijwaring = pihak ketiga ditarik ke dalam perkara.', 'Voeging = pihak ketiga ditarik; Tussenkomst = mengajukan eksepsi; Vrijwaring = mendukung penggugat.', 'Ketiganya memiliki pengertian sama.', 'Voeging dan tussenkomst merupakan putusan hakim, sedangkan vrijwaring merupakan alat bukti.'], 'B', 'Voeging: mendukung. Tussenkomst: kepentingan sendiri. Vrijwaring: ditarik. Ini materi prioritas ujian.'],
      ['Urutan yang paling tepat dalam pengajuan intervensi menurut modul adalah ....', ['Hakim menjatuhkan putusan akhir, kemudian pihak ketiga mengajukan gugatan.', 'Pihak ketiga mengidentifikasi kepentingan hukum, mengajukan permohonan, hakim mempertimbangkan, kemudian menjatuhkan putusan sela.', 'Pihak ketiga langsung masuk ke persidangan tanpa permohonan.', 'Penggugat mengubah gugatan menjadi laporan polisi.', 'Tergugat langsung dinyatakan kalah.'], 'B', 'Tahapan: identifikasi kepentingan hukum, ajukan permohonan kepada hakim yang memeriksa, hakim mempertimbangkan, lalu putusan sela mengabulkan atau menolak.'],
      ['Putusan yang dijatuhkan dalam proses pemeriksaan untuk memutus persoalan tertentu sebelum putusan akhir mengenai pokok perkara disebut ....', ['Putusan verstek', 'Putusan akhir', 'Putusan sela', 'Putusan pidana', 'Putusan administratif'], 'C', 'Dalam intervensi, putusan sela menentukan apakah pihak ketiga diperbolehkan masuk ke dalam perkara.'],
      ['Citra mengajukan permohonan intervensi dan hakim mengabulkannya. Akibatnya adalah ....', ['Citra otomatis memenangkan perkara.', 'Citra memperoleh kedudukan prosedural sebagai pihak sesuai penetapan hakim dan dapat berpartisipasi berdasarkan hak serta kewajiban yang berlaku.', 'Perkara Ahmad dan Budi otomatis dibatalkan.', 'Citra menjadi hakim dalam perkara tersebut.', 'Ahmad otomatis kehilangan hak menggugat.'], 'B', 'Jika dikabulkan, pihak ketiga memperoleh kedudukan prosedural sesuai putusan sela. Jika ditolak, ia tidak memperoleh kedudukan sebagai pihak melalui permohonan tersebut.'],
      ['Mengapa pihak ketiga tidak otomatis memperoleh legal standing hanya karena mengaku mempunyai kepentingan dalam perkara?', ['Karena pihak ketiga harus mempunyai hubungan keluarga dengan hakim.', 'Karena pihak ketiga harus mengajukan permohonan melalui prosedur yang berlaku dan memperoleh keputusan hakim.', 'Karena legal standing hanya dimiliki penggugat.', 'Karena intervensi hanya berlaku dalam perkara pidana.', 'Karena pihak ketiga harus menjadi saksi terlebih dahulu.'], 'B', 'Putusan sela memberi kedudukan hukum kepada pihak ketiga melalui mekanisme intervensi. Pengakuan sepihak mengenai kepentingan belum cukup untuk menjadikan seseorang pihak dalam perkara.']
    ])],
    ['kasus', 'Studi kasus terpadu', m([
      ['Ahmad menggugat Budi karena tidak membayar utang. Setelah gugatan diajukan, ketua pengadilan menetapkan majelis hakim, lalu ketua majelis menentukan tanggal sidang dan memerintahkan juru sita memanggil para pihak. Urutan tindakan yang tepat adalah ....', ['PHS → PMH → gugatan → pemanggilan', 'Gugatan → PMH → PHS → pemanggilan', 'PMH → gugatan → pemanggilan → PHS', 'Pemanggilan → gugatan → PMH → PHS', 'Gugatan → PHS → pembuktian → PMH'], 'B', 'Setelah gugatan diajukan: PMH (menetapkan majelis hakim), PHS (menetapkan hari sidang dan persiapan pemanggilan), lalu pemanggilan para pihak.'],
      ['Ahmad hanya meminta agar Budi membayar utang Rp10.000.000, dan hakim mengabulkan tuntutan itu sesuai dasar dan bukti. Asas yang berkaitan dengan kewenangan para pihak menentukan tuntutan adalah ....', ['Asas keterbukaan', 'Asas hakim bersifat pasif', 'Asas persamaan di hadapan hukum', 'Asas biaya ringan', 'Asas resmi'], 'B', 'Para pihak menentukan sengketa dan apa yang diminta. Hakim memutus dalam ruang lingkup tuntutan dan kewenangannya, tidak menciptakan tuntutan baru.'],
      ['Ahmad menggugat dengan uraian bahwa Budi meminjam uang dan belum melunasinya, serta meminta Budi dihukum membayar. Budi lalu mengajukan keberatan bahwa pengadilan tidak berwenang secara relatif. Bagian yang menunjukkan jawaban Budi adalah ....', ['Posita', 'Petitum', 'Eksepsi', 'Relaas', 'PMH'], 'C', 'Budi tidak membantah fakta pinjaman, tetapi mempersoalkan kewenangan pengadilan, sehingga jawabannya adalah eksepsi.'],
      ['Ahmad memiliki perjanjian tertulis, sedangkan seorang saksi melihat sendiri penyerahan uang kepada Budi. Kedua alat bukti tersebut secara berurutan adalah ....', ['Surat dan saksi', 'Saksi dan pengakuan', 'Pengakuan dan sumpah', 'Persangkaan dan surat', 'Sumpah dan persangkaan'], 'A', 'Perjanjian tertulis adalah bukti surat; keterangan orang yang melihat langsung peristiwa adalah bukti saksi.'],
      ['Budi tidak hadir di persidangan, padahal pemanggilan terhadapnya belum dilakukan sesuai prosedur. Apa yang seharusnya diperhatikan hakim?', ['Langsung menjatuhkan putusan verstek.', 'Langsung memenangkan Ahmad.', 'Memeriksa terlebih dahulu apakah persyaratan pemanggilan dan persyaratan verstek lainnya terpenuhi.', 'Mengubah Budi menjadi saksi.', 'Menghentikan perkara tanpa pemeriksaan.'], 'C', 'Ketidakhadiran tergugat tidak otomatis membuat verstek dapat dijatuhkan. Pemanggilan yang sah dan patut adalah persoalan penting.'],
      ['Budi mengakui pernah menerima pinjaman Rp10.000.000 dari Ahmad, tetapi mengaku telah membayar Rp5.000.000. Apa yang masih harus diperiksa?', ['Apakah Budi pernah menerima pinjaman.', 'Apakah benar pembayaran Rp5.000.000 telah dilakukan dan bagaimana pengaruhnya terhadap sisa kewajiban.', 'Apakah Ahmad merupakan hakim.', 'Apakah perjanjian utang termasuk putusan sela.', 'Apakah Ahmad dapat menjadi pihak ketiga.'], 'B', 'Penerimaan pinjaman sudah diakui, tetapi pembayaran sebagian masih perlu diperiksa. Jika terbukti, hal itu relevan untuk menentukan sisa kewajiban.'],
      ['Ahmad dan Budi bersengketa tanah. Citra masuk ke perkara untuk membantu Ahmad memenangkan perkara, bukan untuk mengklaim tanah sebagai miliknya. Jenis intervensi yang tepat adalah ....', ['Tussenkomst', 'Vrijwaring', 'Voeging', 'Verstek', 'Eksepsi'], 'C', 'Citra masuk untuk mendukung salah satu pihak, yaitu Ahmad. Itulah ciri voeging.'],
      ['Dalam perkara yang sama, Citra menyatakan bahwa tanah yang disengketakan adalah miliknya sendiri dan meminta kepentingannya diperiksa. Jenis intervensi yang tepat adalah ....', ['Voeging', 'Tussenkomst', 'Vrijwaring', 'Eksepsi', 'Putusan verstek'], 'B', 'Citra memperjuangkan kepentingan hukum miliknya sendiri, sehingga jenisnya tussenkomst.'],
      ['Budi meminta pihak ketiga ditarik ke dalam perkara karena menurut hubungan hukum yang ada, pihak ketiga itu seharusnya menjamin atau menanggung akibat hukum bila Budi dinyatakan bertanggung jawab. Jenis intervensinya adalah ....', ['Voeging', 'Tussenkomst', 'Vrijwaring', 'Replik', 'Duplik'], 'C', 'Pihak ketiga tidak masuk atas kemauannya sendiri, tetapi ditarik melalui mekanisme hukum oleh salah satu pihak: vrijwaring.'],
      ['Citra mengajukan permohonan intervensi karena mengklaim punya kepentingan hukum atas tanah, tetapi hakim menolaknya melalui putusan sela. Akibatnya adalah ....', ['Citra otomatis menjadi penggugat.', 'Citra otomatis memenangkan sengketa.', 'Citra tidak memperoleh kedudukan sebagai pihak melalui permohonan intervensi tersebut.', 'Ahmad dan Budi otomatis kalah.', 'Perkara otomatis berubah menjadi pidana.'], 'C', 'Permohonan intervensi yang ditolak tidak memberi kedudukan prosedural sebagai pihak melalui mekanisme tersebut. Penolakan itu juga tidak otomatis menjawab seluruh kemungkinan upaya hukum lain.'],
      ['Manakah urutan proses perkara perdata yang paling sesuai dengan peta konsep dalam modul?', ['Pembuktian → gugatan → PMH → pemanggilan → putusan', 'Gugatan → PMH → PHS → pemanggilan → perdamaian → pemeriksaan dan jawaban → pembuktian → intervensi sesuai ketentuan → putusan', 'Pemanggilan → gugatan → intervensi → PMH → PHS', 'Putusan → pembuktian → gugatan → perdamaian', 'Gugatan → putusan → pemanggilan → pembuktian'], 'B', 'Jawaban B adalah peta pembelajaran seluruh materi, bukan berarti semua perkara memiliki tahapan identik. Prosedur rinci mengikuti ketentuan untuk jenis perkara yang diperiksa.']
    ])]
  ];
  var all = [], banks = [];
  bab.forEach(function (b) { all = all.concat(b[2]); banks.push({ id: 'hap-' + b[0], title: b[1], course: C, questions: b[2] }); });
  banks.unshift({ id: 'hap-semua', title: 'Seluruh materi (Bab I–X dan studi kasus)', course: C, questions: all });
  banks.push({
    id: 'hap-mini', title: 'Mini ujian 12 soal', course: C,
    questions: m([
      ['Apa perbedaan utama hukum perdata materiil dan hukum acara perdata?', ['Materiil mengatur hak dan kewajiban, acara mengatur cara menegakkannya', 'Materiil mengatur hakim, acara mengatur polisi', 'Keduanya sama', 'Materiil mengatur sidang, acara mengatur perjanjian'], 'A', 'Materiil = hak dan kewajiban; acara = tata cara menegakkannya melalui pengadilan.'],
      ['Asas yang membatasi hakim agar tidak mengganti sendiri tuntutan penggugat adalah ...', ['Keterbukaan', 'Hakim bersifat pasif', 'Biaya ringan', 'Persamaan hukum'], 'B', 'Para pihak yang menentukan ruang lingkup tuntutan; hakim tidak membuat tuntutan baru.'],
      ['HIR secara historis terutama berlaku di ...', ['Sumatra dan Kalimantan', 'Seluruh dunia', 'Jawa dan Madura', 'Luar Jawa dan Madura'], 'C', 'HIR: Jawa dan Madura. RBg: luar Jawa dan Madura.'],
      ['Lembaga yang menangani perceraian Muslim dalam kewenangannya adalah ...', ['Peradilan Umum', 'Peradilan Militer', 'Peradilan TUN', 'Peradilan Agama'], 'D', 'Peradilan Agama menangani perkawinan dan kewarisan Islam.'],
      ['Bagian gugatan yang berisi alasan dan dasar hukum disebut ...', ['Posita', 'Petitum', 'Relaas', 'Eksepsi'], 'A', 'Posita menjawab mengapa penggugat menuntut; petitum menjawab apa yang diminta.'],
      ['Penetapan untuk menentukan majelis hakim disebut ...', ['PHS', 'PMH', 'Relaas', 'Renvoi'], 'B', 'PMH = Penetapan Majelis Hakim; PHS = Penetapan Hari Sidang.'],
      ['Dokumen resmi yang mencatat pelaksanaan pemanggilan adalah ...', ['Petitum', 'Posita', 'Relaas', 'PHS'], 'C', 'Relaas panggilan dibuat juru sita untuk mencatat pelaksanaan pemanggilan.'],
      ['Keberatan terhadap kewenangan relatif pengadilan termasuk ...', ['Pengakuan', 'Bantahan pokok perkara', 'Pembuktian', 'Eksepsi'], 'D', 'Eksepsi adalah keberatan prosedural, misalnya soal kewenangan pengadilan.'],
      ['Pasal 164 HIR membahas ...', ['Alat bukti', 'Penetapan majelis', 'Intervensi', 'Gugatan'], 'A', 'Pasal 164 HIR mengatur lima alat bukti: surat, saksi, persangkaan, pengakuan, sumpah.'],
      ['Pihak ketiga masuk untuk mendukung salah satu pihak disebut ...', ['Tussenkomst', 'Voeging', 'Vrijwaring', 'Verstek'], 'B', 'Voeging = mendukung salah satu pihak.'],
      ['Pihak ketiga memperjuangkan kepentingan hukumnya sendiri disebut ...', ['Voeging', 'Vrijwaring', 'Tussenkomst', 'Eksepsi'], 'C', 'Tussenkomst = membela kepentingan sendiri.'],
      ['Pihak ketiga ditarik ke dalam perkara disebut ...', ['Voeging', 'Tussenkomst', 'Pengakuan', 'Vrijwaring'], 'D', 'Vrijwaring = pihak ketiga ditarik ke dalam perkara.']
    ])
  });
  window.MO_EXAM_BANKS = (window.MO_EXAM_BANKS || []).concat(banks);
})();
